  revalidatePath("/admin/site-editor");
  revalidatePath("/news");
  revalidatePath("/");
}

export async function deleteNews(id: number) {
  await requireAuth();
  await prisma.news.delete({ where: { id } });
  revalidatePath("/admin/site-editor");
  revalidatePath("/новини");
  revalidatePath("/");
}

// ===== SHOP PRODUCTS =====

export type ShopProductInput = {
  name: string;
  description: string;
  price: number;
  oldPrice?: number | null;
  category: string;
  emoji: string;
