            БЛ
          </div>
          <h1 className="text-2xl font-black" style={{ color: "#1a2744" }}>
            ЛДБЛ Admin
          </h1>
          <p className="text-gray-500 text-sm mt-1">Увійдіть для управління лігою</p>
        </div>

        <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow p-6 space-y-4">
