              style={{ "--tw-ring-color": "#1a2744" } as React.CSSProperties}
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1.5">Пароль</label>
            <input
              name="password"
              type="password"
              required
