  addedAt: string;
};

type Candidate = {
  phone: string;
  name: string;
  source: "chat" | "player";
  hp?: number;
  position?: string;
};

type ModLogEntry = {
  id: number;
  action: string;
  modName: string;
  targetName: string;
  details: string;
  createdAt: string;
};

type ShopProduct = {
  id: number;
  name: string;
  emoji: string;
  category: string;
  price: number;
  showInChat: boolean;
  chatPriority: boolean;
};

const ACTION_LABELS: Record<string, string> = {
  ban: "🚫 Бан",
  unban: "✅ Розбан",
  warn: "⚠️ Попередження",
  autoban: "🤖 Автобан (3 варни)",
  mute: "🔇 Вимкнення",
  unmute: "🔊 Увімкнення",
  deleteMsg: "🗑 Видалення повід.",
  pin: "📌 Закріплення",
  slowMode: "🐢 Повільний режим",
  quiz: "❓ Вікторина",
};

export default function ChatModeratorsTab({
  settings,
  shopProducts,
}: {
  settings: Record<string, string>;
  shopProducts: ShopProduct[];
}) {
  const [moderators, setModerators] = useState<Moderator[]>([]);
  const [candidates, setCandidates] = useState<Candidate[]>([]);
  const [log, setLog] = useState<ModLogEntry[]>([]);
  const [search, setSearch] = useState("");
  const [section, setSection] = useState<"mods" | "hp" | "shop-chat" | "log">("mods");
  const [pending, startTransition] = useTransition();
  const [status, setStatus] = useState("");
  const [chatOnline, setChatOnline] = useState(true);

  // HP settings
  const [joinBonus, setJoinBonus] = useState(Number(settings["chat.hp.joinBonus"] ?? "25"));
  const [referralBonus, setReferralBonus] = useState(Number(settings["chat.hp.referralBonus"] ?? "50"));
  const [hpSaved, setHpSaved] = useState(false);
  const [showHpRules, setShowHpRules] = useState(false);

  // Shop chat settings (local copy for optimistic UI)
  const [products, setProducts] = useState<ShopProduct[]>(shopProducts);
  const [shopSaving, setShopSaving] = useState<number | null>(null);

  async function fetchModerators() {
    try {
      const res = await fetch(proxy("/api/chat/moderators"));
      if (!res.ok) throw new Error();
      const data = await res.json();
      setModerators(data.moderators || []);
      setChatOnline(true);
    } catch {
      setChatOnline(false);
    }
  }

  async function fetchCandidates() {
    const list: Candidate[] = [];
    const seen = new Set<string>();

    // 1. Chat guests (registered in chat)
    try {
      const res = await fetch(proxy("/api/chat/guests"));
      if (res.ok) {
        const data = await res.json();
        for (const g of data.guests || []) {
          if (!seen.has(g.phone)) {
            seen.add(g.phone);
            list.push({ phone: g.phone, name: g.name, source: "chat", hp: g.hp });
          }
        }
      }
    } catch {}

    // 2. Players from main DB (via GuestContacts — players who registered in chat)
    try {
      const res = await fetch("/api/guest-contacts");
      if (res.ok) {
        const data = await res.json();
        for (const g of data.contacts || data.guests || []) {
          const name = g.name || `${g.firstName || ""} ${g.lastName || ""}`.trim();
          if (g.phone && name && !seen.has(g.phone)) {
            seen.add(g.phone);
            list.push({ phone: g.phone, name, source: "chat", hp: g.hp });
          }
        }
      }
    } catch {}

    setCandidates(list);
  }

  async function fetchLog() {
    try {
      const res = await fetch(proxy("/api/chat/mod/log"));
      if (res.ok) {
        const data = await res.json();
        setLog(data.log || []);
      }
    } catch {}
  }

  useEffect(() => {
    fetchModerators();
    fetchCandidates();
  }, []);

  function addModerator(phone: string) {
    startTransition(async () => {
      try {
        const res = await fetch(proxy("/api/chat/moderators/add"), {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ phone }),
        });
        if (res.ok) {
          setStatus("✅ Модератора додано");
          setTimeout(() => setStatus(""), 2000);
          await fetchModerators();
        }
      } catch {
        setStatus("❌ Помилка");
        setTimeout(() => setStatus(""), 2000);
      }
    });
  }

  function removeModerator(phone: string) {
    if (!confirm("Зняти повноваження модератора?")) return;
    startTransition(async () => {
      await fetch(proxy("/api/chat/moderators/remove"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone }),
      });
      setStatus("✅ Повноваження знято");
      setTimeout(() => setStatus(""), 2000);
      await fetchModerators();
    });
  }

  function saveHpSettings() {
    startTransition(async () => {
      await updateSiteTexts({
        "chat.hp.joinBonus": String(joinBonus),
        "chat.hp.referralBonus": String(referralBonus),
      });
      setHpSaved(true);
      setTimeout(() => setHpSaved(false), 2000);
    });
  }

  async function toggleShowInChat(product: ShopProduct) {
    const newVal = !product.showInChat;
    setProducts((prev) => prev.map((p) => p.id === product.id ? { ...p, showInChat: newVal } : p));
    setShopSaving(product.id);
    await updateShopProductChatSettings(product.id, { showInChat: newVal });
    setShopSaving(null);
  }

  async function toggleChatPriority(product: ShopProduct) {
    const newVal = !product.chatPriority;
    setProducts((prev) => prev.map((p) => p.id === product.id ? { ...p, chatPriority: newVal } : p));
    setShopSaving(product.id);
    await updateShopProductChatSettings(product.id, { chatPriority: newVal });
    setShopSaving(null);
  }

  async function updateEmoji(product: ShopProduct, emoji: string) {
    setProducts((prev) => prev.map((p) => p.id === product.id ? { ...p, emoji } : p));
    setShopSaving(product.id);
    await updateShopProductChatSettings(product.id, { emoji });
    setShopSaving(null);
  }

  const modPhones = new Set(moderators.map((m) => m.phone));
  const filtered = candidates.filter(
    (g) =>
      !modPhones.has(g.phone) &&
      g.name.toLowerCase().includes(search.toLowerCase())
  );

  const SECTIONS = [
    { id: "mods" as const, label: "🛡 Модератори" },
    { id: "hp" as const, label: "⚡ HP та реферали" },
    { id: "shop-chat" as const, label: "🛒 Товари в чаті" },
    { id: "log" as const, label: "📋 Журнал дій" },
  ];

  return (
    <div className="space-y-5">
      {/* Section tabs */}
      <div className="flex gap-2 border-b pb-3 flex-wrap items-center">
        {SECTIONS.map((s) => (
          <button
            key={s.id}
            onClick={() => { setSection(s.id); if (s.id === "log") fetchLog(); }}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${section === s.id ? "text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"}`}
            style={section === s.id ? { backgroundColor: "#1a2744" } : {}}
          >
            {s.label}
          </button>
        ))}
        <div className="ml-auto flex items-center gap-3">
          {status && <span className="text-sm font-medium text-green-600">{status}</span>}
          <span className="text-xs font-semibold px-2 py-1 rounded-lg bg-green-100 text-green-700">
            🟢 Чат онлайн
          </span>
        </div>
      </div>

      {/* MODERATORS */}
      {section === "mods" && (
        <div className="space-y-5">
          {/* Current moderators */}
          <div>
            <h2 className="font-bold text-gray-800 mb-3">Поточні модератори ({moderators.length})</h2>
            {moderators.length === 0 ? (
              <p className="text-gray-400 text-sm py-4 text-center">Модераторів ще немає</p>
            ) : (
              <div className="space-y-2">
                {moderators.map((m) => (
                  <div key={m.phone} className="bg-purple-50 border border-purple-200 rounded-xl flex items-center gap-3 px-4 py-3">
                    <div className="w-10 h-10 rounded-full bg-purple-200 flex-shrink-0 text-lg font-bold text-purple-700 flex items-center justify-center">
                      {(m.name || "?")[0]}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-bold text-gray-800 text-sm">{m.name || m.phone}</div>
                      <div className="text-xs text-gray-400">{m.phone} · Додано {new Date(m.addedAt).toLocaleDateString("uk-UA")}</div>
                    </div>
                    <span className="text-xs bg-purple-200 text-purple-800 px-2 py-1 rounded-lg font-bold mr-2">🛡 Модератор</span>
                    <button
                      onClick={() => removeModerator(m.phone)}
                      disabled={pending}
                      className="text-xs text-red-400 hover:text-red-600 hover:underline disabled:opacity-50"
                    >
                      Зняти
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Add moderator */}
          <div className="bg-gray-50 border rounded-xl p-4 space-y-3">
            <h3 className="font-bold text-gray-700">Призначити модератора</h3>
            <p className="text-xs text-gray-400">
              Вибрати зі зареєстрованих учасників чату. Роль вступає в силу миттєво.
            </p>


            <input
              className="w-full border rounded-lg px-3 py-2 text-sm"
              placeholder="Пошук за ім'ям..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />

            {candidates.length === 0 && (
              <p className="text-xs text-gray-400 text-center py-2">
                Список порожній — жодного учасника в чаті ще немає.
              </p>
            )}

            <div className="space-y-1 max-h-60 overflow-y-auto">
              {filtered.map((g) => (
                <div key={g.phone} className="bg-white border rounded-lg flex items-center gap-3 px-3 py-2">
                  <div className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center text-sm font-bold text-gray-600 flex-shrink-0">
                    {g.name[0]}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-medium text-sm text-gray-800">{g.name}</div>
                    <div className="text-xs text-gray-400">
                      {g.phone}
                      {g.hp !== undefined && <span className="ml-1">· ⚡ {g.hp} HP</span>}
                    </div>
                  </div>
                  <button
                    onClick={() => addModerator(g.phone)}
                    disabled={pending}
                    className="text-xs px-3 py-1.5 rounded-lg font-bold text-white disabled:opacity-50"
                    style={{ backgroundColor: "#7c3aed" }}
                  >
                    + Призначити
                  </button>
                </div>
              ))}
              {search && filtered.length === 0 && candidates.length > 0 && (
                <p className="text-xs text-gray-400 text-center py-2">Нічого не знайдено за &ldquo;{search}&rdquo;</p>
              )}
            </div>
          </div>

          {/* Info */}
          <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 text-xs text-blue-700 space-y-1">
            <p className="font-bold mb-1">Можливості модератора в чаті:</p>
            <p>• Бан на 15 хв / 24 год / назавжди</p>
            <p>• Попередження ⚠️ (3 варни = автобан на 24 год)</p>
            <p>• Вимкнення (mute) на 30 хвилин</p>
            <p>• Видалення та закріплення повідомлень</p>
            <p>• Запуск вікторини (30 секунд, 4 варіанти)</p>
            <p>• Повільний режим (1 повід. кожні 30 сек)</p>
          </div>
        </div>
      )}

      {/* HP & REFERRAL SETTINGS */}
      {section === "hp" && (
        <div className="space-y-6">
          {/* HP Accrual */}
          <section>
            <div className="flex items-center justify-between border-b pb-2 mb-4">
              <h2 className="font-bold text-gray-800 text-base">⚡ Нарахування HP</h2>
              <button
                type="button"
                onClick={() => setShowHpRules((v) => !v)}
                className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg border border-blue-200 text-blue-600 hover:bg-blue-50 transition-colors"
              >
                <span className="w-4 h-4 rounded-full border border-blue-400 flex items-center justify-center font-black text-blue-500 text-xs leading-none">?</span>
                {showHpRules ? "Сховати правила" : "Правила нарахування"}
              </button>
            </div>

            {showHpRules && (
              <div className="mb-4 bg-blue-50 border border-blue-200 rounded-xl p-4 space-y-3 text-sm">
                <p className="font-bold text-blue-800">Як нараховуються HP:</p>
                <div className="space-y-2 text-blue-700">
                  <div className="flex items-start gap-2">
                    <span className="text-lg leading-none mt-0.5">🆕</span>
                    <div>
                      <span className="font-semibold">Реєстрація в чаті</span>
                      <span className="ml-1 text-blue-600">— +{joinBonus} HP</span>
                      <p className="text-xs text-blue-500 mt-0.5">При першому вході та заповненні форми реєстрації</p>
                    </div>
                  </div>
                  <div className="flex items-start gap-2">
                    <span className="text-lg leading-none mt-0.5">🔗</span>
                    <div>
                      <span className="font-semibold">Реферальне запрошення</span>
                      <span className="ml-1 text-blue-600">— +{referralBonus} HP</span>
                      <p className="text-xs text-blue-500 mt-0.5">Нараховується реферу, коли новий учасник реєструється за його посиланням</p>
                    </div>
                  </div>
                  <div className="flex items-start gap-2">
                    <span className="text-lg leading-none mt-0.5">🏆</span>
                    <div>
                      <span className="font-semibold">Для чого потрібні HP</span>
                      <p className="text-xs text-blue-500 mt-0.5">HP — внутрішня валюта чату. Використовується для рейтингу учасників, голосування MVP та покупок у магазині</p>
                    </div>
                  </div>
                  <div className="flex items-start gap-2">
                    <span className="text-lg leading-none mt-0.5">⚙️</span>
                    <div>
                      <span className="font-semibold">Зміна значень</span>
                      <p className="text-xs text-blue-500 mt-0.5">Нові значення застосовуються тільки до нових реєстрацій — вже нарахованi HP не змінюються</p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            <p className="text-xs text-gray-500 mb-4">
              HP (Health Points) — внутрішня валюта чату. Нараховується при реєстрації та за реферальні запрошення.
            </p>
            <div className="bg-gray-50 rounded-xl border p-4 space-y-4">
              <div className="flex items-center gap-4">
                <div className="flex-1">
                  <div className="text-sm font-semibold text-gray-800">HP за реєстрацію</div>
                  <div className="text-xs text-gray-500 mt-0.5">Скільки HP отримує новий учасник при першому вході в чат</div>
                </div>
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    min={0}
                    max={9999}
                    value={joinBonus}
                    onChange={(e) => setJoinBonus(Number(e.target.value))}
                    className="border border-gray-200 rounded-lg px-3 py-2 text-sm w-24 font-mono text-center focus:outline-none focus:ring-2 focus:ring-orange-400"
                  />
                  <span className="text-sm text-gray-500 font-bold">HP</span>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex-1">
                  <div className="text-sm font-semibold text-gray-800">HP за реферала</div>
                  <div className="text-xs text-gray-500 mt-0.5">Скільки HP отримує учасник, коли хтось реєструється за його реферальним посиланням</div>
                </div>
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    min={0}
                    max={9999}
                    value={referralBonus}
                    onChange={(e) => setReferralBonus(Number(e.target.value))}
                    className="border border-gray-200 rounded-lg px-3 py-2 text-sm w-24 font-mono text-center focus:outline-none focus:ring-2 focus:ring-orange-400"
                  />
                  <span className="text-sm text-gray-500 font-bold">HP</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-4 mt-4">
              <button
                onClick={saveHpSettings}
                disabled={pending}
                className="px-6 py-2.5 rounded-lg font-bold text-white text-sm disabled:opacity-60"
                style={{ backgroundColor: "#1a2744" }}
              >
                {pending ? "Зберігається..." : "Зберегти HP налаштування"}
              </button>
              {hpSaved && <span className="text-green-600 text-sm font-medium">✓ Збережено!</span>}
            </div>
          </section>

          {/* Referral Link */}
          <section>
            <h2 className="font-bold text-gray-800 mb-1 text-base border-b pb-2">🔗 Реферальні посилання</h2>
            <p className="text-xs text-gray-500 mb-4">
              Кожен учасник чату має унікальне реферальне посилання. Телефон учасника є його реферальним кодом.
            </p>
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 space-y-3 text-sm">
              <div>
                <div className="font-semibold text-gray-800 mb-1">Формат реферального посилання:</div>
                <code className="bg-white border border-amber-200 rounded-lg px-3 py-2 block text-xs font-mono text-gray-700 break-all">
                  https://[домен-чату]/?ref=[ТЕЛЕФОН_УЧАСНИКА]
                </code>
              </div>
              <div>
                <div className="font-semibold text-gray-800 mb-1">Приклад:</div>
                <code className="bg-white border border-amber-200 rounded-lg px-3 py-2 block text-xs font-mono text-gray-700 break-all">
                  https://chat.lbbl.lviv.ua/?ref=380991234567
                </code>
              </div>
              <div className="text-xs text-gray-600 bg-white border border-amber-100 rounded-lg p-3 space-y-1">
                <p className="font-semibold">Як працює:</p>
                <p>1. Учасник ділиться своїм посиланням</p>
                <p>2. Новий користувач реєструється за цим посиланням</p>
                <p>3. Учасник-реферер отримує <strong>{referralBonus} HP</strong> автоматично</p>
                <p>4. Новий учасник отримує <strong>{joinBonus} HP</strong> за реєстрацію</p>
              </div>
            </div>
          </section>
        </div>
      )}

      {/* SHOP PRODUCTS IN CHAT */}
      {section === "shop-chat" && (
        <div className="space-y-4">
          <div>
            <h2 className="font-bold text-gray-800 mb-1 text-base border-b pb-2">🛒 Іконки товарів у чаті</h2>
            <p className="text-xs text-gray-500 mb-4">
              Керуйте тим, які товари з Магазину відображаються в чаті та їх пріоритетністю. Іконка (emoji) відображається поруч з назвою товару.
            </p>
          </div>

          {products.length === 0 ? (
            <div className="text-center py-12 text-gray-400 text-sm border-2 border-dashed rounded-xl">
              Товарів у магазині ще немає
            </div>
          ) : (
            <div className="space-y-2">
              {products.map((product) => (
                <div
                  key={product.id}
                  className={`bg-white border rounded-xl px-4 py-3 flex items-center gap-3 transition-opacity ${shopSaving === product.id ? "opacity-60" : ""}`}
                >
                  {/* Emoji editor */}
                  <div className="flex-shrink-0">
                    <input
                      type="text"
                      value={product.emoji}
                      onChange={(e) => {
                        const val = Array.from(e.target.value).slice(-2).join("") || product.emoji;
                        setProducts((prev) => prev.map((p) => p.id === product.id ? { ...p, emoji: val } : p));
                      }}
                      onBlur={(e) => {
                        if (e.target.value !== shopProducts.find((p) => p.id === product.id)?.emoji) {
                          updateEmoji(product, e.target.value || "🏀");
                        }
                      }}
                      className="w-12 h-12 text-2xl text-center border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-400 cursor-text"
                      title="Іконка товару (emoji)"
                      maxLength={4}
                    />
                  </div>

                  {/* Product info */}
                  <div className="flex-1 min-w-0">
                    <div className="font-semibold text-gray-800 text-sm truncate">{product.name}</div>
                    <div className="text-xs text-gray-400">{product.category} · {product.price} грн</div>
                  </div>

                  {/* Show in chat toggle */}
                  <label className="flex items-center gap-2 cursor-pointer flex-shrink-0">
                    <div
                      onClick={() => toggleShowInChat(product)}
                      className={`relative w-10 h-5 rounded-full transition-colors cursor-pointer ${product.showInChat ? "bg-orange-500" : "bg-gray-300"}`}
                    >
                      <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow transition-transform ${product.showInChat ? "translate-x-5" : "translate-x-0.5"}`} />
                    </div>
                    <span className="text-xs text-gray-600 w-20">
                      {product.showInChat ? "В чаті" : "Прихований"}
                    </span>
                  </label>

                  {/* Priority toggle */}
                  <label className={`flex items-center gap-2 cursor-pointer flex-shrink-0 ${!product.showInChat ? "opacity-40 pointer-events-none" : ""}`}>
                    <div
                      onClick={() => product.showInChat && toggleChatPriority(product)}
                      className={`relative w-10 h-5 rounded-full transition-colors cursor-pointer ${product.chatPriority ? "bg-yellow-400" : "bg-gray-300"}`}
                    >
                      <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow transition-transform ${product.chatPriority ? "translate-x-5" : "translate-x-0.5"}`} />
                    </div>
                    <span className="text-xs text-gray-600 w-20">
                      {product.chatPriority ? "⭐ Пріоритет" : "Звичайний"}
                    </span>
                  </label>

                  {shopSaving === product.id && (
                    <span className="text-xs text-gray-400 flex-shrink-0">збереження...</span>
                  )}
                </div>
              ))}
            </div>
          )}

          <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 text-xs text-blue-700 space-y-1">
            <p className="font-bold mb-1">Як це працює:</p>
            <p>• <strong>В чаті</strong> — товар відображається в списку покупок чату</p>
            <p>• <strong>Пріоритет ⭐</strong> — товар показується першим / виділяється у списку</p>
            <p>• <strong>Іконка</strong> — emoji відображається поруч з назвою товару в чаті</p>
            <p>• Зміни зберігаються автоматично при перемиканні</p>
          </div>
        </div>
      )}

      {/* MOD LOG */}
      {section === "log" && (
        <div>
          <h2 className="font-bold text-gray-800 mb-3">Журнал дій модераторів ({log.length})</h2>
          {log.length === 0 ? (
            <p className="text-gray-400 text-sm py-4 text-center">Дій поки не було</p>
          ) : (
            <div className="space-y-2 max-h-[500px] overflow-y-auto">
              {log.map((entry) => (
                <div key={entry.id} className="bg-white border rounded-xl px-4 py-3 flex items-start gap-3">
                  <div className="flex-shrink-0 text-sm mt-0.5">
                    {(ACTION_LABELS[entry.action] || "📝").split(" ")[0]}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-bold text-sm text-gray-800">{ACTION_LABELS[entry.action] || entry.action}</span>
                      {entry.targetName && <span className="text-xs text-gray-500">→ <b>{entry.targetName}</b></span>}
                    </div>
                    <div className="text-xs text-gray-400 mt-0.5">
                      Мод: {entry.modName}
                      {entry.details && <span className="ml-2 text-gray-300">· {entry.details}</span>}
                    </div>
                  </div>
                  <div className="text-xs text-gray-300 flex-shrink-0 whitespace-nowrap">
                    {new Date(entry.createdAt).toLocaleString("uk-UA", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

structure.app/admin/site-editor/tabs/ColorsTab.tsx:
"use client";

import { useState, useTransition, forwardRef, useImperativeHandle } from "react";
import { updateSiteColors } from "@/actions/site-settings";
import type { SaveHandle } from "../SiteEditorClient";

const DEFAULT_COLORS: Record<string, string> = {
  // === СЕКЦІЇ САЙТУ ===
  "colors.headerBg":        "#0f172a",
  "colors.headerText":      "#f8fafc",
  "colors.heroBg":          "#0f172a",
  "colors.heroTitle":       "#ffffff",
  "colors.heroSubtitle":    "#94a3b8",
  "colors.pageBg":          "#f8fafc",
  "colors.cardBg":          "#ffffff",
  "colors.cardBorder":      "#e2e8f0",
  "colors.tableBg":         "#0f172a",
  "colors.tableHeaderText": "#ffffff",
  "colors.tableRowOdd":     "#f1f5f9",
  "colors.tableRowEven":    "#ffffff",
  "colors.newsBg":          "#f1f5f9",
  "colors.footerBg":        "#0f172a",
  "colors.footerText":      "#94a3b8",
  "colors.footerLink":      "#f97316",
  "colors.footerCopyright": "#475569",
  // === КНОПКИ ===
  "colors.btnBlue":         "#2563eb",
  "colors.btnOrange":       "#f97316",
  "colors.btnNavy":         "#0f172a",
  "colors.btnRed":          "#dc2626",
  "colors.btnSchedule":     "#2563eb",
  "colors.btnHero":         "#f97316",
  "colors.btnDonate":       "#ea580c",
  "colors.btnChat":         "#1e293b",
  // Legacy fallback (не показуються в UI, але зберігаються для сумісності)
  "colors.navy":            "#0f172a",
  "colors.orange":          "#f97316",
  "colors.blue":            "#2563eb",
  "colors.red":             "#dc2626",
  "colors.bg":              "#f8fafc",
};

type ColorField = { key: string; label: string };

const SECTION_FIELDS: ColorField[] = [
  { key: "colors.headerBg",        label: "Хедер — фон навбару" },
  { key: "colors.headerText",      label: "Хедер — колір тексту меню" },
  { key: "colors.heroBg",          label: "Hero — фон банера" },
  { key: "colors.heroTitle",       label: "Hero — колір заголовку" },
  { key: "colors.heroSubtitle",    label: "Hero — колір підзаголовку" },
  { key: "colors.pageBg",          label: "Фон сторінок (загальний)" },
  { key: "colors.cardBg",          label: "Картки — фон" },
  { key: "colors.cardBorder",      label: "Картки — рамка" },
  { key: "colors.tableBg",         label: "Таблиця — фон заголовку" },
  { key: "colors.tableHeaderText", label: "Таблиця — текст заголовку" },
  { key: "colors.tableRowOdd",     label: "Таблиця — непарні рядки" },
  { key: "colors.tableRowEven",    label: "Таблиця — парні рядки" },
  { key: "colors.newsBg",          label: "Новини — фон секції" },
  { key: "colors.footerBg",        label: "Footer — фон підвалу" },
  { key: "colors.footerText",      label: "Footer — колір тексту" },
  { key: "colors.footerLink",      label: "Footer — колір посилань" },
  { key: "colors.footerCopyright", label: "Footer — copyright текст" },
];

const BUTTON_FIELDS: ColorField[] = [
  { key: "colors.btnBlue",     label: "+1 Штрафний (синя кнопка)" },
  { key: "colors.btnOrange",   label: "+2 Двоочковий (помаранчева кнопка)" },
  { key: "colors.btnNavy",     label: "+3 Триочковий (темна кнопка)" },
  { key: "colors.btnRed",      label: "LIVE бейдж / Фол (червона)" },
  { key: "colors.btnSchedule", label: "Переглянути розклад" },
  { key: "colors.btnHero",     label: "Кнопки Hero (Барахолка, Магазин...)" },
  { key: "colors.btnDonate",   label: "Кнопка Donate" },
  { key: "colors.btnChat",     label: "Кнопка Балачка" },
];

function SectionHeader({ title }: { title: string }) {
  return (
    <div style={{
      fontSize: 12,
      fontWeight: 700,
      color: "#64748b",
      textTransform: "uppercase",
      letterSpacing: "0.08em",
      margin: "24px 0 10px",
      paddingBottom: 6,
      borderBottom: "2px solid #e2e8f0",
    }}>
      {title}
    </div>
  );
}

function ColorRow({ field, value, onChange }: { field: ColorField; value: string; onChange: (v: string) => void }) {
  return (
    <div className="flex items-center gap-3">
      <label htmlFor={field.key} className="text-sm font-medium text-gray-700 flex-1 min-w-0">
        {field.label}
      </label>
      <div className="flex items-center gap-2 flex-shrink-0">
        <input
          type="color"
          id={field.key}
          value={value || "#ffffff"}
          onChange={(e) => onChange(e.target.value)}
          className="w-9 h-9 rounded-lg border border-gray-200 cursor-pointer p-0.5"
        />
        <input
          type="text"
          value={value || ""}
          onChange={(e) => onChange(e.target.value)}
          className="border border-gray-200 rounded-lg px-2 py-1.5 text-xs w-24 focus:outline-none font-mono"
        />
        <div className="w-7 h-7 rounded border border-gray-200 flex-shrink-0" style={{ backgroundColor: value }} />
      </div>
    </div>
  );
}

const ColorsTab = forwardRef<SaveHandle, { settings: Record<string, string> }>(
  function ColorsTab({ settings }, ref) {
    const [pending, startTransition] = useTransition();
    const [saved, setSaved] = useState(false);
    const [colors, setColors] = useState<Record<string, string>>(() => {
      const c: Record<string, string> = {};
      for (const key of Object.keys(DEFAULT_COLORS)) {
        c[key] = settings[key] || DEFAULT_COLORS[key];
      }
      return c;
    });

    const handleSave = () => {
      startTransition(async () => {
        await updateSiteColors(colors);
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
      });
    };

    useImperativeHandle(ref, () => ({ save: handleSave }));

    const handleReset = () => setColors({ ...DEFAULT_COLORS });

    const set = (key: string, val: string) => setColors((prev) => ({ ...prev, [key]: val }));

    const c = colors;

    return (
      <div className="space-y-1">

        <SectionHeader title="🎨 Секції сайту" />
        <div className="space-y-2">
          {SECTION_FIELDS.map((f) => (
            <ColorRow key={f.key} field={f} value={c[f.key] ?? ""} onChange={(v) => set(f.key, v)} />
          ))}
        </div>

        <SectionHeader title="🔘 Кнопки" />
        <div className="space-y-2">
          {BUTTON_FIELDS.map((f) => (
            <ColorRow key={f.key} field={f} value={c[f.key] ?? ""} onChange={(v) => set(f.key, v)} />
          ))}
        </div>

        {/* Live preview */}
        <div className="border rounded-xl overflow-hidden mt-6">
          <div className="px-4 py-2 text-xs text-gray-500 bg-gray-50 border-b font-medium uppercase tracking-wider">
            Попередній перегляд
          </div>
          <div style={{ backgroundColor: c["colors.pageBg"] || "#f1f5f9" }}>
            {/* Header */}
            <div className="px-4 py-2 text-sm font-bold mb-0" style={{ backgroundColor: c["colors.headerBg"], color: c["colors.headerText"] }}>
              ЛІГА — Хедер / Навбар
            </div>
            {/* Hero */}
            <div className="px-4 py-3 text-center" style={{ backgroundColor: c["colors.heroBg"] }}>
              <div className="text-sm font-black mb-1" style={{ color: c["colors.heroTitle"] }}>Заголовок Hero</div>
              <div className="text-xs mb-2" style={{ color: c["colors.heroSubtitle"] }}>Підзаголовок секції</div>
              <div className="flex gap-2 justify-center flex-wrap">
                <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnHero"] }}>Барахолка</span>
                <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnChat"] }}>Балачка</span>
                <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnDonate"] }}>Donate</span>
                <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnSchedule"] }}>Розклад</span>
              </div>
            </div>
            {/* Cards + Table */}
            <div className="grid grid-cols-2 gap-2 p-3">
              <div className="rounded p-2 text-xs text-gray-600" style={{ backgroundColor: c["colors.cardBg"], border: `1px solid ${c["colors.cardBorder"]}` }}>
                Картка матчу
              </div>
              <div className="rounded overflow-hidden">
                <div className="px-2 py-1 text-xs font-bold" style={{ backgroundColor: c["colors.tableBg"], color: c["colors.tableHeaderText"] }}>Таблиця</div>
                <div className="px-2 py-1 text-xs" style={{ backgroundColor: c["colors.tableRowOdd"] || "#f8fafc" }}>Рядок 1</div>
                <div className="px-2 py-1 text-xs" style={{ backgroundColor: c["colors.tableRowEven"] || "#ffffff" }}>Рядок 2</div>
              </div>
            </div>
            {/* Live tracker buttons */}
            <div className="flex gap-2 px-3 pb-3 flex-wrap">
              <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnBlue"] }}>+1</span>
              <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnOrange"] }}>+2</span>
              <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnNavy"] }}>+3</span>
              <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: c["colors.btnRed"] }}>LIVE</span>
            </div>
          </div>
          {/* Footer */}
          <div className="px-4 py-3" style={{ backgroundColor: c["colors.footerBg"] }}>
            <span className="text-xs font-bold mr-2" style={{ color: c["colors.footerText"] }}>Footer</span>
            <span className="text-xs mr-2" style={{ color: c["colors.footerLink"] }}>посилання</span>
            <span className="text-xs" style={{ color: c["colors.footerCopyright"] }}>© copyright</span>
          </div>
        </div>

        <div className="flex items-center gap-4 mt-4">
          <button
            onClick={handleSave}
            disabled={pending}
            className="px-6 py-2.5 rounded-lg font-bold text-white text-sm disabled:opacity-60"
            style={{ backgroundColor: "#1a2744" }}
          >
            {pending ? "Зберігається..." : "Зберегти кольори"}
          </button>
          <button
            onClick={handleReset}
            className="px-4 py-2.5 rounded-lg border border-gray-300 text-sm font-medium text-gray-700 hover:bg-gray-50"
          >
            Скинути до стандарту
          </button>
          {saved && <span className="text-green-600 text-sm font-medium">✓ Збережено!</span>}
        </div>
      </div>
    );
  }
);

export default ColorsTab;

structure.app/admin/site-editor/tabs/ContactsTab.t:
"use client";

import { useState, useTransition, forwardRef, useImperativeHandle } from "react";
import { updateSiteTexts } from "@/actions/site-settings";
import type { SaveHandle } from "../SiteEditorClient";

const ContactsTab = forwardRef<SaveHandle, { settings: Record<string, string> }>(
  function ContactsTab({ settings }, ref) {
    const [pending, startTransition] = useTransition();
    const [saved, setSaved] = useState(false);

    const [title, setTitle] = useState(settings["contacts.title"] ?? "Баскетбол у Львові — Ліга ESCULAB");
    const [subtitle, setSubtitle] = useState(settings["contacts.subtitle"] ?? "Офіційна баскетбольна ліга міста Львова");
    const [address, setAddress] = useState(
      settings["contacts.address"] || settings["contact.address"] || "м. Львів, вул. Спортивна"
    );
    const [email, setEmail] = useState(
      settings["contacts.email"] || settings["contact.email"] || "info@basket.lviv.ua"
    );
    const [website, setWebsite] = useState(
      settings["contacts.website"] || settings["contact.website"] || "basket.lviv.ua"
    );
    const [facebook, setFacebook] = useState(
      settings["contacts.facebook"] || settings["social.facebook"] || ""
    );
    const [instagram, setInstagram] = useState(
      settings["contacts.instagram"] || settings["social.instagram"] || ""
    );
    const [youtube, setYoutube] = useState(settings["contacts.youtube"] ?? "");
    const [telegram, setTelegram] = useState(settings["social.telegram"] ?? "");
    const [cardNumber, setCardNumber] = useState(settings["donate.cardNumber"] ?? "");
    const [cardName, setCardName] = useState(settings["donate.cardName"] ?? "");
    const [cardBank, setCardBank] = useState(settings["donate.cardBank"] ?? "");
    const [donateLabel, setDonateLabel] = useState(settings["donate.label"] ?? "Допомогти клубу Donate");

    const handleSave = () => {
      startTransition(async () => {
        await updateSiteTexts({
          // contacts.* — для сторінки /contacts
          "contacts.title":    title,
          "contacts.subtitle": subtitle,
          "contacts.address":  address,
          "contacts.email":    email,
          "contacts.website":  website,
          "contacts.facebook": facebook,
          "contacts.instagram": instagram,
          "contacts.youtube":  youtube,
          // contact.* (singular) — для FooterWrapper головного сайту
          "contact.address":   address,
          "contact.email":     email,
          "contact.website":   website,
          // social.* — для micro-apps та FooterWrapper
          "social.facebook":   facebook,
          "social.instagram":  instagram,
          "social.telegram":   telegram,
          "social.youtube":    youtube,
          // donate
          "donate.cardNumber": cardNumber,
          "donate.cardName":   cardName,
          "donate.cardBank":   cardBank,
          "donate.label":      donateLabel,
        });
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
      });
    };

    useImperativeHandle(ref, () => ({ save: handleSave }));

    return (
      <div className="space-y-6">
        {/* Basic info */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="md:col-span-2">
            <label className="block text-sm font-semibold text-gray-700 mb-1">Назва організації</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
            />
          </div>

          <div className="md:col-span-2">
            <label className="block text-sm font-semibold text-gray-700 mb-1">Підзаголовок</label>
            <input
              type="text"
              value={subtitle}
              onChange={(e) => setSubtitle(e.target.value)}
              className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Адреса</label>
            <input
              type="text"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
            />
          </div>

          <div className="md:col-span-2">
            <label className="block text-sm font-semibold text-gray-700 mb-1">Сайт</label>
            <input
              type="text"
              value={website}
              onChange={(e) => setWebsite(e.target.value)}
              className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
            />
          </div>
        </div>

        {/* Social links */}
        <div className="border-t pt-5">
          <div className="text-sm font-semibold text-gray-700 mb-3">Соціальні мережі</div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="flex items-center gap-2 text-sm font-semibold mb-1" style={{ color: "#1877f2" }}>
                <span className="w-4 h-4 rounded inline-block" style={{ backgroundColor: "#1877f2" }} />
                Facebook URL
              </label>
              <input
                type="url"
                placeholder="https://facebook.com/..."
                value={facebook}
                onChange={(e) => setFacebook(e.target.value)}
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-semibold mb-1" style={{ color: "#e1306c" }}>
                <span className="w-4 h-4 rounded inline-block" style={{ background: "linear-gradient(45deg,#f09433,#e6683c,#dc2743,#cc2366,#bc1888)" }} />
                Instagram URL
              </label>
              <input
                type="url"
                placeholder="https://instagram.com/..."
                value={instagram}
                onChange={(e) => setInstagram(e.target.value)}
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-semibold mb-1" style={{ color: "#0088cc" }}>
                <span className="w-4 h-4 rounded inline-block" style={{ backgroundColor: "#0088cc" }} />
                Telegram URL
              </label>
              <input
                type="url"
                placeholder="https://t.me/..."
                value={telegram}
                onChange={(e) => setTelegram(e.target.value)}
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-semibold mb-1" style={{ color: "#ff0000" }}>
                <span className="w-4 h-4 rounded inline-block" style={{ backgroundColor: "#ff0000" }} />
                YouTube URL
              </label>
              <input
                type="url"
                placeholder="https://youtube.com/..."
                value={youtube}
                onChange={(e) => setYoutube(e.target.value)}
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
              />
            </div>
          </div>
          <p className="text-xs text-gray-400 mt-2">
            Соцмережі відображаються у футері всіх сервісів (Барахолка, Курси, Магазин, Новини) та на сторінці Контакти.
          </p>
        </div>

        {/* Donate / Bank card */}
        <div className="border-t pt-5">
          <div className="flex items-center gap-2 mb-3">
            <span className="text-lg">❤️</span>
            <div className="text-sm font-semibold text-gray-700">Кнопка Donate — банківська картка</div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <label className="block text-sm font-semibold text-gray-700 mb-1">Текст кнопки</label>
              <input
                type="text"
                value={donateLabel}
                onChange={(e) => setDonateLabel(e.target.value)}
                placeholder="Допомогти клубу Donate"
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Номер картки</label>
              <input
                type="text"
                value={cardNumber}
                onChange={(e) => setCardNumber(e.target.value)}
                placeholder="4149 6090 1234 5678"
                maxLength={23}
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-300"
              />
              <p className="text-xs text-gray-400 mt-1">16–19 цифр, пробіли допустимі</p>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Назва банку</label>
              <input
                type="text"
                value={cardBank}
