"use client";

import { useState, useEffect, useRef, useTransition } from "react";
import type { GameRow } from "../SiteEditorClient";

// ── Photo Gallery ──────────────────────────────────────────────────────────────

type Album = { gameId: number; photos: string[]; coverPhoto: string | null; createdAt: string };

function AlbumEditor({ album: initialAlbum, game }: { album: Album; game: GameRow | undefined }) {
  const [photos, setPhotos] = useState<string[]>(initialAlbum.photos);
  const [cover, setCover] = useState<string | null>(initialAlbum.coverPhoto);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState("");
  const [saved, setSaved] = useState(false);

  const title = game
    ? `${game.homeTeam.shortName} vs ${game.awayTeam.shortName}`
    : `Матч #${initialAlbum.gameId}`;

  const date = game
    ? new Date(game.scheduledAt).toLocaleDateString("uk-UA", { day: "numeric", month: "short" })
    : "";

  async function handleUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const files = Array.from(e.target.files ?? []);
    if (!files.length) return;

    const available = 10 - photos.length;
    const toUpload = files.slice(0, available);
    if (toUpload.length < files.length) {
      setError(`Можна додати ще ${available} фото (максимум 10)`);
    } else {
      setError("");
    }

    setUploading(true);
    const newUrls: string[] = [];
    for (const file of toUpload) {
      const fd = new FormData();
      fd.append("file", file);
      fd.append("gameId", String(initialAlbum.gameId));
      try {
        const res = await fetch("/api/gallery", { method: "POST", body: fd, credentials: "include" });
        const data = await res.json();
        if (res.ok && data.url) {
          newUrls.push(data.url);
        } else {
          setError(data.error ?? "Помилка завантаження");
        }
      } catch {
        setError("Помилка мережі");
      }
    }
    const updated = [...photos, ...newUrls];
    setPhotos(updated);
    if (!cover && updated.length > 0) setCover(updated[0]);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
    setUploading(false);
    e.target.value = "";
  }

  async function handleDelete(url: string) {
    const res = await fetch("/api/gallery", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ gameId: initialAlbum.gameId, url }),
      credentials: "include",
    });
    if (res.ok) {
      const updated = photos.filter((p) => p !== url);
      setPhotos(updated);
      if (cover === url) setCover(updated[0] ?? null);
    }
  }

  async function handleSetCover(url: string) {
    const res = await fetch("/api/gallery", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ gameId: initialAlbum.gameId, url }),
      credentials: "include",
    });
    if (res.ok) setCover(url);
  }

  return (
    <div className="border border-gray-100 rounded-2xl p-4 bg-gray-50">
      <div className="flex items-center justify-between mb-3">
        <div>
          <div className="font-bold text-gray-800 text-sm">{title}</div>
          {date && <div className="text-xs text-gray-400">{date}</div>}
        </div>
        <div className="flex items-center gap-3">
          <span
            className={`text-xs font-semibold px-2 py-0.5 rounded-full ${
              photos.length >= 10 ? "bg-red-100 text-red-600" : "bg-orange-50 text-orange-600"
            }`}
          >
            {photos.length}/10 фото
          </span>
          {photos.length < 10 && (
            <label
              className={`cursor-pointer px-3 py-1.5 rounded-lg text-xs font-bold text-white ${
                uploading ? "opacity-60 cursor-wait" : "hover:opacity-90"
              }`}
              style={{ backgroundColor: "#1a2744" }}
            >
              {uploading ? "Завантаження..." : "+ Додати фото"}
              <input
                type="file"
                accept="image/*"
                multiple
                className="hidden"
                onChange={handleUpload}
                disabled={uploading}
              />
            </label>
          )}
        </div>
      </div>

      {error && <div className="text-xs text-red-500 mb-2">{error}</div>}
      {saved && <div className="text-xs text-green-600 mb-2 font-medium">✓ Фото збережено!</div>}

      {photos.length > 0 ? (
        <div className="grid grid-cols-5 gap-2">
          {photos.map((url, i) => (
            <div
              key={i}
              className="relative group rounded-lg overflow-hidden bg-gray-200"
              style={{ aspectRatio: "1" }}
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={url} alt={`фото ${i + 1}`} className="w-full h-full object-cover" />

              {cover === url && (
                <div className="absolute top-1 left-1 bg-orange-500 text-white text-[9px] font-bold px-1.5 py-0.5 rounded leading-tight">
                  обкладинка
                </div>
              )}

              <div className="absolute inset-0 bg-black/55 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-1.5">
                {cover !== url && (
                  <button
                    onClick={() => handleSetCover(url)}
                    className="text-[10px] bg-orange-500 text-white px-2 py-1 rounded font-bold"
                  >
                    Обкладинка
                  </button>
                )}
                <button
                  onClick={() => handleDelete(url)}
                  className="text-[10px] bg-red-500 text-white px-2 py-1 rounded font-bold"
                >
                  Видалити
                </button>
              </div>
            </div>
          ))}

          {Array.from({ length: 10 - photos.length }).map((_, i) => (
            <div
              key={`empty-${i}`}
              className="rounded-lg bg-gray-100 border-2 border-dashed border-gray-200 flex items-center justify-center"
              style={{ aspectRatio: "1" }}
            >
              <span className="text-gray-300 text-xl leading-none">+</span>
            </div>
          ))}
        </div>
      ) : (
        <div className="text-center py-6 text-gray-400 text-sm border-2 border-dashed border-gray-200 rounded-xl">
          Фото ще не додані. Натисніть &quot;+ Додати фото&quot;
        </div>
      )}
    </div>
  );
}

// ── Videos ────────────────────────────────────────────────────────────────────

type VideoItem = {
  id: number;
  title: string;
  url: string;
  thumbnail: string | null;
  type: string;
  publishedAt: string;
};

const VIDEO_TYPES = [
  { value: "highlights", label: "Хайлайти" },
  { value: "full", label: "Повний матч" },
  { value: "moments", label: "Кращі моменти" },
];

function VideosSection() {
  const [videos, setVideos] = useState<VideoItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("highlights");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);
  const [, startTransition] = useTransition();

  useEffect(() => {
    fetch("/api/videos")
      .then((r) => r.json())
      .then((d) => setVideos(d.videos ?? []))
      .finally(() => setLoading(false));
  }, []);

  async function handleUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!title.trim()) { setError("Введіть назву відео"); return; }
    setError("");
    setUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      fd.append("title", title.trim());
      fd.append("type", type);
      const res = await fetch("/api/videos", { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok) { setError(data.error || "Помилка завантаження"); return; }
      setVideos((v) => [data, ...v]);
      setTitle("");
      setSuccess("Відео завантажено!");
      setTimeout(() => setSuccess(""), 2500);
    } finally {
      setUploading(false);
      if (fileRef.current) fileRef.current.value = "";
    }
  }

  function handleDelete(id: number) {
    if (!confirm("Видалити відео?")) return;
    startTransition(async () => {
      const res = await fetch("/api/videos", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id }) });
      if (res.ok) setVideos((v) => v.filter((x) => x.id !== id));
    });
  }

  return (
    <div className="space-y-4">
      {/* Upload form */}
      <div className="bg-gray-50 rounded-xl p-4 border space-y-3">
        <h4 className="font-bold text-gray-700 text-sm">Додати відео</h4>
        <div className="flex gap-3 flex-wrap items-end">
          <div className="flex-1 min-w-48">
            <label className="text-xs text-gray-500 mb-1 block">Назва</label>
            <input
              className="w-full border rounded-lg px-3 py-2 text-sm"
              placeholder="Хайлайти матчу..."
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
          </div>
          <div className="w-40">
            <label className="text-xs text-gray-500 mb-1 block">Тип</label>
            <select
              className="w-full border rounded-lg px-3 py-2 text-sm"
              value={type}
              onChange={(e) => setType(e.target.value)}
            >
              {VIDEO_TYPES.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
            </select>
          </div>
          <div>
            <input ref={fileRef} type="file" accept="video/*" className="hidden" onChange={handleUpload} />
            <button
              onClick={() => { if (!title.trim()) { setError("Введіть назву відео"); return; } fileRef.current?.click(); }}
              disabled={uploading}
              className="px-5 py-2 rounded-lg text-sm font-bold text-white disabled:opacity-50"
              style={{ backgroundColor: "#f97316" }}
            >
              {uploading ? "Завантаження..." : "Обрати відео"}
            </button>
          </div>
        </div>
        {error && <div className="text-xs text-red-500">{error}</div>}
        {success && <div className="text-xs text-green-600 font-medium">{success}</div>}
      </div>

      {/* Videos list */}
      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm">Завантаження...</div>
      ) : videos.length === 0 ? (
        <div className="text-center py-8 text-gray-400 text-sm border-2 border-dashed border-gray-200 rounded-xl">
          Відео ще не завантажені
        </div>
      ) : (
        <div className="space-y-3">
          {videos.map((v) => (
            <div key={v.id} className="flex items-center gap-4 bg-white rounded-xl border p-3">
              <div className="w-20 h-14 rounded-lg bg-gray-900 flex items-center justify-center flex-shrink-0 overflow-hidden">
                <video src={v.url} className="w-full h-full object-cover" muted />
              </div>
              <div className="flex-1 min-w-0">
                <div className="font-bold text-sm text-gray-800 truncate">{v.title}</div>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-xs text-orange-600 font-medium bg-orange-50 px-2 py-0.5 rounded">
                    {VIDEO_TYPES.find((t) => t.value === v.type)?.label ?? v.type}
                  </span>
                  <span className="text-xs text-gray-400">
                    {new Date(v.publishedAt).toLocaleDateString("uk-UA")}
                  </span>
                </div>
              </div>
              <button
                onClick={() => handleDelete(v.id)}
                className="text-xs px-2 py-1 rounded border border-red-200 text-red-500 hover:bg-red-50 flex-shrink-0"
              >
                Вид.
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── Main Tab ──────────────────────────────────────────────────────────────────

type Section = "videos" | "photos";

export default function GalleryTab({ games }: { games: GameRow[] }) {
  const [section, setSection] = useState<Section>("videos");
  const [albums, setAlbums] = useState<Album[] | null>(null);
  const gamesMap = Object.fromEntries(games.map((g) => [g.id, g]));

  useEffect(() => {
    if (section === "photos" && albums === null) {
      fetch("/api/gallery")
        .then((r) => r.json())
        .then((data) => setAlbums(data.albums ?? []))
        .catch(() => setAlbums([]));
    }
  }, [section, albums]);

  return (
    <div className="space-y-5">
      <div>
        <h3 className="text-base font-semibold text-gray-800">Медіа / Галерея</h3>
        <p className="text-sm text-gray-500 mt-0.5">Завантажуйте відео та фотографії матчів — вони відображатимуться у розділі &quot;Медіа&quot; на сайті.</p>
      </div>

      {/* Section switcher */}
      <div className="flex gap-2">
        <button
          onClick={() => setSection("videos")}
          className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${
            section === "videos"
              ? "text-white"
              : "bg-gray-100 text-gray-600 hover:bg-gray-200"
          }`}
          style={section === "videos" ? { backgroundColor: "#f46f10" } : {}}
        >
          Відео
        </button>
        <button
          onClick={() => setSection("photos")}
          className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${
            section === "photos"
              ? "text-white"
              : "bg-gray-100 text-gray-600 hover:bg-gray-200"
          }`}
          style={section === "photos" ? { backgroundColor: "#1a2744" } : {}}
        >
          Фотогалерея
        </button>
      </div>

      {/* Videos section */}
      {section === "videos" && <VideosSection />}

      {/* Photos section */}
      {section === "photos" && (
        albums === null ? (
          <div className="text-center py-12 text-gray-400 text-sm">Завантаження...</div>
        ) : albums.length === 0 ? (
          <div className="text-center py-12 text-gray-400 text-sm">Альбоми відсутні</div>
        ) : (
          <div className="space-y-4">
            <p className="text-sm text-gray-500">До кожного матчу можна додати до 10 фотографій. Перша завантажена або вибрана стає обкладинкою альбому.</p>
            {albums.map((album) => (
              <AlbumEditor key={album.gameId} album={album} game={gamesMap[album.gameId]} />
            ))}
          </div>
        )
      )}
    </div>
  );
}

structure.app/admin/site-editor/tabs/GuestContacts:
"use client";

import { useState, useEffect } from "react";

type Contact = {
  id: number;
  phone: string;
  firstName: string;
  lastName: string;
  refCode: string | null;
  hp: number;
  role: string;
  createdAt: string;
};

export default function GuestContactsTab() {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [loading, setLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<number | null>(null);

  useEffect(() => {
    fetch("/api/guest-contacts")
      .then((r) => r.json())
      .then((d) => setContacts(d.contacts ?? []))
      .finally(() => setLoading(false));
  }, []);

  const handleDelete = async (c: Contact) => {
    if (!confirm(`Видалити контакт ${c.firstName} ${c.lastName} (${c.phone})?`)) return;
    setDeletingId(c.id);
    try {
      const response = await fetch("/api/guest-contacts", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: c.id }),
      });
      if (!response.ok) {
        let errorMsg = "Не вдалося видалити контакт";
        const contentType = response.headers.get("content-type");
        if (contentType?.includes("application/json")) {
          try {
            const error = await response.json();
            errorMsg = error.error || errorMsg;
          } catch {
            errorMsg = `Помилка сервера (${response.status})`;
          }
        }
        alert(`Помилка: ${errorMsg}`);
        setDeletingId(null);
        return;
      }
      setContacts((prev) => prev.filter((x) => x.id !== c.id));
    } catch (err) {
      alert(`Помилка мережі: ${err instanceof Error ? err.message : "Unknown error"}`);
    } finally {
      setDeletingId(null);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-base font-semibold text-gray-800">Контакти гостей</h3>
          <p className="text-sm text-gray-500 mt-0.5">
            Учасники, які зареєструвались через Чат ЛДБЛ
          </p>
        </div>
        <div className="text-sm font-bold text-gray-700 bg-gray-100 px-3 py-1.5 rounded-lg">
          {contacts.length} учасників
        </div>
      </div>

      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm">Завантаження...</div>
      ) : contacts.length === 0 ? (
        <div className="text-center py-12 text-gray-400 text-sm border-2 border-dashed border-gray-200 rounded-xl">
          Поки що немає зареєстрованих учасників
        </div>
      ) : (
        <div className="overflow-x-auto rounded-xl border">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gray-50 text-left text-xs text-gray-500">
                <th className="px-4 py-3 font-semibold">#</th>
                <th className="px-4 py-3 font-semibold">Ім&apos;я</th>
                <th className="px-4 py-3 font-semibold">Прізвище</th>
                <th className="px-4 py-3 font-semibold">Телефон</th>
                <th className="px-4 py-3 font-semibold">Роль</th>
                <th className="px-4 py-3 font-semibold">HP</th>
                <th className="px-4 py-3 font-semibold">Реферал</th>
                <th className="px-4 py-3 font-semibold">Дата</th>
                <th className="px-4 py-3 font-semibold"></th>
              </tr>
            </thead>
            <tbody>
              {contacts.map((c, i) => (
                <tr key={c.id} className="border-t hover:bg-gray-50">
                  <td className="px-4 py-3 text-gray-400">{i + 1}</td>
                  <td className="px-4 py-3 font-medium text-gray-800">{c.firstName}</td>
                  <td className="px-4 py-3 font-medium text-gray-800">{c.lastName}</td>
                  <td className="px-4 py-3 font-mono text-gray-600">{c.phone}</td>
                  <td className="px-4 py-3">
                    <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${
                      c.role === "parent" ? "bg-blue-100 text-blue-700" :
                      c.role === "player" ? "bg-green-100 text-green-700" :
                      "bg-gray-100 text-gray-600"
                    }`}>
                      {c.role === "parent" ? "👨‍👩‍👦 батько/мати" : c.role === "player" ? "🏀 гравець" : "гість"}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <span className="font-bold text-orange-600">{c.hp} HP</span>
                  </td>
                  <td className="px-4 py-3 text-gray-400 font-mono text-xs">{c.refCode || "—"}</td>
                  <td className="px-4 py-3 text-gray-400 text-xs">
                    {new Date(c.createdAt).toLocaleDateString("uk-UA", { day: "numeric", month: "short", year: "numeric" })}
                  </td>
                  <td className="px-4 py-3">
                    <button
                      onClick={() => handleDelete(c)}
                      disabled={deletingId === c.id}
                      className="text-xs text-red-400 hover:text-red-600 hover:underline disabled:opacity-40"
                    >
                      {deletingId === c.id ? "..." : "Видалити"}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

structure.app/admin/site-editor/tabs/HeaderTab.tsx:
"use client";

import { useState, useTransition, forwardRef, useImperativeHandle } from "react";
import { updateHeaderSettings } from "@/actions/site-settings";
import type { SaveHandle } from "../SiteEditorClient";


const HeaderTab = forwardRef<SaveHandle, { settings: Record<string, string> }>(
  function HeaderTab({ settings }, ref) {
  const [pending, startTransition] = useTransition();
  const [saved, setSaved] = useState(false);

  const [height, setHeight] = useState(parseInt(settings["header.height"] ?? "64", 10));
  const [fontSize, setFontSize] = useState(parseInt(settings["header.fontSizeNav"] ?? "14", 10));
  const [activeStyle, setActiveStyle] = useState(settings["header.activeStyle"] ?? "underline");
  const [logoPosition, setLogoPosition] = useState(settings["header.logoPosition"] ?? "left");

  const handleSave = () => {
    startTransition(async () => {
      await updateHeaderSettings({
        "header.height": String(height),
        "header.fontSizeNav": String(fontSize),
        "header.activeStyle": activeStyle,
        "header.logoPosition": logoPosition,
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    });
  };

  useImperativeHandle(ref, () => ({ save: handleSave }));

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Висота хедера: <span className="text-orange-500">{height}px</span>
          </label>
          <input
            type="range"
            min={48}
            max={120}
            value={height}
            onChange={(e) => setHeight(parseInt(e.target.value))}
            className="w-full"
          />
          <div className="flex justify-between text-xs text-gray-400 mt-1">
            <span>48px</span>
            <span>120px</span>
          </div>
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Розмір шрифту навігації: <span className="text-orange-500">{fontSize}px</span>
          </label>
          <input
            type="range"
            min={11}
            max={20}
            value={fontSize}
            onChange={(e) => setFontSize(parseInt(e.target.value))}
            className="w-full"
          />
          <div className="flex justify-between text-xs text-gray-400 mt-1">
            <span>11px</span>
            <span>20px</span>
          </div>
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Стиль актив  ого пункту
          </label>
          <div className="flex gap-3">
            {["underline", "background", "color"].map((style) => (
              <label key={style} className="flex items-center gap-2 cursor-pointer text-sm text-gray-700">
                <input
                  type="radio"
                  value={style}
                  checked={activeStyle === style}
                  onChange={() => setActiveStyle(style)}
                />
                {style === "underline" ? "Підкреслення" : style === "background" ? "Фон" : "Колір"}
              </label>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Позиція логотипу
          </label>
          <div className="flex gap-3">
            {["left", "center"].map((pos) => (
              <label key={pos} className="flex items-center gap-2 cursor-pointer text-sm text-gray-700">
                <input
                  type="radio"
                  value={pos}
                  checked={logoPosition === pos}
                  onChange={() => setLogoPosition(pos)}
                />
                {pos === "left" ? "Ліворуч" : "По центру"}
              </label>
            ))}
          </div>
        </div>
      </div>

      {/* Preview */}
      <div className="border rounded-xl overflow-hidden">
        <div className="px-4 py-2 text-xs text-gray-500 bg-gray-50 border-b font-medium uppercase tracking-wider">
          Попередній перегляд хедера
        </div>
        <div
          className="flex items-center px-6 text-white"
          style={{
            backgroundColor: settings["colors.navy"] ?? "#1a2744",
            height: `${height}px`,
            justifyContent: logoPosition === "center" ? "center" : "space-between",
          }}
        >
          <div className="flex items-center gap-2">
            <div
              className="w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs"
              style={{ backgroundColor: settings["colors.orange"] ?? "#f97316" }}
            >
              БЛ
            </div>
            <span className="font-bold">ЛІГА ESCULAB</span>
          </div>
          {logoPosition !== "center" && (
            <nav className="flex gap-1">
              {["Новини", "Розклад", "Змагання"].map((label, i) => (
                <span
                  key={label}
                  className="px-3 rounded"
                  style={{
                    fontSize: `${fontSize}px`,
                    color: i === 0
                      ? (settings["colors.orange"] ?? "#f97316")
                      : "rgba(255,255,255,0.8)",
                    borderBottom: i === 0 && activeStyle === "underline"
                      ? `2px solid ${settings["colors.orange"] ?? "#f97316"}`
                      : "none",
                    backgroundColor: i === 0 && activeStyle === "background"
                      ? "rgba(255,255,255,0.15)"
                      : "transparent",
                  }}
                >
                  {label}
                </span>
              ))}
            </nav>
          )}
        </div>
      </div>

      <div className="flex items-center gap-4">
        <button
          onClick={handleSave}
          disabled={pending}
          className="px-6 py-2.5 rounded-lg font-bold text-white text-sm disabled:opacity-60"
          style={{ backgroundColor: "#1a2744" }}
        >
          {pending ? "Зберігається..." : "Зберегти налаштування хедера"}
        </button>
        {saved && <span className="text-green-600 text-sm font-medium">✓ Збережено!</span>}
      </div>
    </div>
  );
}
);

export default HeaderTab;

structure.app/admin/site-editor/tabs/ImagesTab.tsx:
"use client";

import { useState, useTransition } from "react";
import { updateSiteTexts } from "@/actions/site-settings";

type ImageType = "logo" | "ogImage" | "heroBg" | "headerBg" | "footerBg" | "pageBg";

const IMAGE_CONFIG: Array<{ type: ImageType; label: string; hint: string }> = [
  { type: "logo", label: "Логотип", hint: "Замінює текстовий кружечок 'БЛ'" },
  { type: "ogImage", label: "OG Image", hint: "1200×630px для соцмереж" },
  { type: "heroBg", label: "Фон Hero-банера", hint: "Головна сторінка, секція hero" },
  { type: "headerBg", label: "Фон хедера", hint: "Замінює колір хедера" },
  { type: "footerBg", label: "Фон футера", hint: "Замінює колір футера" },
  { type: "pageBg", label: "Фон всіх сторінок", hint: "Тло за контентом" },
];

const BANNER_SLOTS = [
  {
    slot: "top",
    label: "Банер вгорі сторінок",
    hint: "Відображається під хедером на всіх сторінках. Рекомендований розмір: 728×90px",
  },
  {
    slot: "bottom",
    label: "Банер внизу сторінок",
    hint: "Відображається перед футером на всіх сторінках. Рекомендований розмір: 728×90px",
  },
];

function ImageUploadRow({
  config,
  currentUrl,
}: {
  config: (typeof IMAGE_CONFIG)[0];
  currentUrl: string;
}) {
  const [url, setUrl] = useState(currentUrl);
  const [uploading, setUploading] = useState(false);
  const [pending, startTransition] = useTransition();
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = "";
    setError(null);
    setUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      fd.append("type", config.type);
      const res = await fetch("/api/upload", { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok || data.error) {
        setError(data.error || `HTTP ${res.status}`);
        return;
      }
      if (data.url) {
        setUrl(data.url);
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
      }
    } catch (err) {
      setError(String(err));
    } finally {
      setUploading(false);
    }
  };

  const handleClear = () => {
    startTransition(async () => {
      await updateSiteTexts({ [`images.${config.type}`]: "" });
      setUrl("");
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    });
  };

  const isPlaceholder = url === "[base64]";
  const isDataUrl = url.startsWith("data:") || isPlaceholder;

  return (
    <div className="flex items-start gap-4 py-4 border-b last:border-0">
      <div className="flex-1">
        <div className="font-semibold text-gray-800 text-sm">{config.label}</div>
        <div className="text-xs text-gray-500 mt-0.5">{config.hint}</div>
        {url && (
          <div className="mt-2 flex items-center gap-2">
            <span className="text-xs text-green-600 font-mono">
              {isPlaceholder ? "[base64 — завантажено]" : isDataUrl ? `[base64, ${Math.round(url.length / 1024)}KB]` : url}
            </span>
            <button onClick={handleClear} disabled={pending} className="text-xs text-red-500 hover:text-red-700">
              Видалити
            </button>
          </div>
        )}
        {error && <div className="mt-1 text-xs text-red-600 font-medium">⚠ {error}</div>}
        {saved && <div className="mt-1 text-xs text-green-600 font-medium">✓ Збережено!</div>}
      </div>
      <div className="flex flex-col items-end gap-2">
        {url && url !== "[base64]" && config.type !== "ogImage" && (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={url}
            alt={config.label}
            className="w-16 h-16 object-contain rounded-lg border bg-gray-50"
            onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
          />
        )}
        {isPlaceholder && config.type !== "ogImage" && (
          <div className="w-16 h-16 rounded-lg border bg-gray-50 flex items-center justify-center text-xs text-gray-400 text-center">збережено</div>
        )}
        <label className="cursor-pointer px-4 py-2 rounded-lg border border-gray-300 text-sm font-medium text-gray-700 hover:bg-gray-50">
          {uploading ? "Завантаження..." : pending ? "Зберігається..." : url ? "Змінити" : "Завантажити"}
          <input
            type="file"
            accept="image/*"
            className="hidden"
            onChange={handleFileChange}
            disabled={uploading || pending}
          />
        </label>
      </div>
    </div>
  );
}

function BannerSlotRow({
  slot,
  label,
  hint,
  currentImg,
  currentUrl,
  currentActive,
}: {
  slot: string;
  label: string;
  hint: string;
  currentImg: string;
  currentUrl: string;
  currentActive: boolean;
}) {
  const [img, setImg] = useState(currentImg);
  const [linkUrl, setLinkUrl] = useState(currentUrl);
  const [active, setActive] = useState(currentActive);
  const [uploading, setUploading] = useState(false);
  const [pending, startTransition] = useTransition();
  const [saved, setSaved] = useState(false);

  const save = (patch: Record<string, string>) => {
    startTransition(async () => {
      await updateSiteTexts(patch);
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    const fd = new FormData();
    fd.append("file", file);
    fd.append("type", `banner-${slot}`);
    try {
      const res = await fetch("/api/upload", { method: "POST", body: fd });
      const data = await res.json();
      if (data.url) {
        setImg(data.url);
        save({ [`banner.${slot}.img`]: data.url });
      }
    } finally {
      setUploading(false);
    }
  };

  const handleSaveUrl = () => {
    save({ [`banner.${slot}.url`]: linkUrl });
  };

  const handleToggleActive = () => {
    const next = !active;
    setActive(next);
    save({ [`banner.${slot}.active`]: next ? "true" : "false" });
  };

  const handleClearImg = () => {
    setImg("");
    save({ [`banner.${slot}.img`]: "" });
  };

  return (
    <div className="border rounded-xl p-4 space-y-3 bg-white">
      {/* Header row */}
      <div className="flex items-start justify-between gap-3">
        <div>
          <div className="font-semibold text-gray-800 text-sm">{label}</div>
          <div className="text-xs text-gray-500 mt-0.5">{hint}</div>
        </div>
        <button
          onClick={handleToggleActive}
          className={`px-3 py-1 rounded-full text-xs font-bold transition-all flex-shrink-0 ${
            active ? "text-white" : "bg-gray-100 text-gray-400"
          }`}
          style={active ? { backgroundColor: "#22c55e" } : {}}
        >
          {active ? "Активний" : "Вимкнено"}
        </button>
      </div>

      {/* Preview */}
      {img && (
        <div className="relative">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={img} alt="Банер" className="w-full max-h-28 object-cover rounded-lg border" />
          <button
            onClick={handleClearImg}
            className="absolute top-2 right-2 bg-red-500 text-white text-xs px-2 py-0.5 rounded-full hover:bg-red-600"
          >
            Видалити
          </button>
        </div>
      )}

      {/* Upload */}
      <label className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 rounded-lg border border-gray-300 text-sm font-medium text-gray-700 hover:bg-gray-50">
        {uploading ? "Завантаження..." : img ? "Змінити зображення" : "Завантажити зображення"}
        <input type="file" accept="image/*" className="hidden" onChange={handleFileChange} disabled={uploading || pending} />
      </label>

      {/* Link URL */}
      <div className="flex gap-2">
        <input
          type="url"
          placeholder="https://посилання-при-кліку.ua"
          className="flex-1 border rounded-lg px-3 py-2 text-sm"
          value={linkUrl}
          onChange={(e) => setLinkUrl(e.target.value)}
        />
        <button
          onClick={handleSaveUrl}
          disabled={pending}
          className="px-4 py-2 rounded-lg text-sm font-bold text-white disabled:opacity-50"
          style={{ backgroundColor: "#1a2744" }}
        >
          Зберегти URL
        </button>
      </div>

      {saved && <div className="text-xs text-green-600 font-medium">✓ Збережено!</div>}
    </div>
  );
}

export default function ImagesTab({ settings }: { settings: Record<string, string> }) {
  return (
    <div className="space-y-8">
      {/* Site images section */}
      <div>
        <h3 className="font-bold text-gray-700 mb-3 text-sm uppercase tracking-wide">Зображення сайту</h3>
        <div className="bg-white rounded-xl border p-4">
          <div style={{ background: "#fef3c7", border: "1px solid #f59e0b", borderRadius: 8, padding: "10px 14px", fontSize: 13, color: "#92400e", marginBottom: 16 }}>
            ⚠️ Зображення зберігаються в базі даних (base64). Максимальний розмір — 512KB. Якщо логотип не відображається — завантажте його знову.
          </div>
          {IMAGE_CONFIG.map((config) => (
            <ImageUploadRow key={config.type} config={config} currentUrl={settings[`images.${config.type}`] ?? ""} />
          ))}
        </div>
      </div>

      {/* Ad banners section */}
      <div>
        <h3 className="font-bold text-gray-700 mb-1 text-sm uppercase tracking-wide">Рекламні банери</h3>
        <p className="text-xs text-gray-500 mb-3">
          Банери відображаються на всіх публічних сторінках сайту. Завантажте зображення і вкажіть URL куди вести при кліку.
        </p>
        <div className="space-y-4">
          {BANNER_SLOTS.map(({ slot, label, hint }) => (
            <BannerSlotRow
              key={slot}
              slot={slot}
              label={label}
              hint={hint}
              currentImg={settings[`banner.${slot}.img`] ?? ""}
              currentUrl={settings[`banner.${slot}.url`] ?? ""}
              currentActive={settings[`banner.${slot}.active`] !== "false"}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

structure.app/admin/site-editor/tabs/NavButtonsTab:
"use client";

import { useState, useTransition, forwardRef, useImperativeHandle } from "react";
import { updateNavigation } from "@/actions/site-settings";
import type { SaveHandle } from "../SiteEditorClient";

interface NavItem {
  href: string;
  label: string;
  visible: boolean;
}

const DEFAULT_ITEMS: NavItem[] = [
  { href: "/news", label: "Медіа", visible: true },
  { href: "/schedule", label: "Розклад", visible: true },
  { href: "/standings", label: "Змагання", visible: true },
  { href: "/leaders", label: "Лідери", visible: true },
  { href: "/teams", label: "Команди", visible: true },
  { href: "/players", label: "Гравці", visible: true },
  { href: "/contacts", label: "Контакти", visible: true },
];

function parseItems(raw: string): NavItem[] {
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && parsed.length > 0) return parsed;
  } catch {}
  return DEFAULT_ITEMS;
}

const NavButtonsTab = forwardRef<SaveHandle, { settings: Record<string, string> }>(
  function NavButtonsTab({ settings }, ref) {
    const [pending, startTransition] = useTransition();
    const [saved, setSaved] = useState(false);
    const [items, setItems] = useState<NavItem[]>(() => parseItems(settings["nav.items"] ?? ""));

    const handleSave = () => {
      startTransition(async () => {
        await updateNavigation(items);
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
      });
    };

    useImperativeHandle(ref, () => ({ save: handleSave }));

    function updateItem(index: number, field: keyof NavItem, value: string | boolean) {
      setItems((prev) => prev.map((item, i) => i === index ? { ...item, [field]: value } : item));
    }

    function moveItem(index: number, direction: -1 | 1) {
      const next = [...items];
      const target = index + direction;
      if (target < 0 || target >= next.length) return;
      [next[index], next[target]] = [next[target], next[index]];
      setItems(next);
    }

    function addItem() {
      setItems((prev) => [...prev, { href: "/", label: "Новий пункт", visible: true }]);
    }

    function removeItem(index: number) {
      setItems((prev) => prev.filter((_, i) => i !== index));
    }

    function resetToDefault() {
      setItems(DEFAULT_ITEMS);
    }

    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-base font-semibold text-gray-800">Пункти навігації</h3>
            <p className="text-sm text-gray-500 mt-0.5">Редагуйте назви, посилання та видимість кнопок у хедері сайту</p>
          </div>
          <button
            onClick={resetToDefault}
            className="px-3 py-1.5 rounded-lg border border-gray-200 text-xs text-gray-500 hover:bg-gray-50"
          >
            Скинути до default
          </button>
        </div>

        <div className="space-y-3">
          {items.map((item, i) => (
            <div
              key={i}
              className="flex items-center gap-3 bg-gray-50 rounded-xl px-4 py-3 border border-gray-100"
              style={{ opacity: item.visible ? 1 : 0.5 }}
            >
              {/* Reorder */}
              <div className="flex flex-col gap-0.5">
                <button
                  onClick={() => moveItem(i, -1)}
                  disabled={i === 0}
                  className="text-gray-400 hover:text-gray-600 disabled:opacity-20 leading-none text-xs"
                  title="Вгору"
                >
                  ▲
                </button>
                <button
                  onClick={() => moveItem(i, 1)}
                  disabled={i === items.length - 1}
                  className="text-gray-400 hover:text-gray-600 disabled:opacity-20 leading-none text-xs"
                  title="Вниз"
                >
                  ▼
                </button>
              </div>

              {/* Index */}
              <span className="text-xs font-bold text-gray-400 w-5 text-center">{i + 1}</span>

              {/* Label */}
              <div className="flex-1 min-w-0">
                <label className="block text-xs text-gray-500 mb-1">Назва</label>
                <input
                  type="text"
                  value={item.label}
                  onChange={(e) => updateItem(i, "label", e.target.value)}
                  className="w-full px-3 py-1.5 rounded-lg border border-gray-200 text-sm font-medium bg-white focus:outline-none focus:ring-2 focus:ring-orange-300"
                />
              </div>

              {/* Href */}
              <div className="flex-1 min-w-0">
                <label className="block text-xs text-gray-500 mb-1">Посилання</label>
                <input
                  type="text"
                  value={item.href}
                  onChange={(e) => updateItem(i, "href", e.target.value)}
                  className="w-full px-3 py-1.5 rounded-lg border border-gray-200 text-sm font-mono bg-white focus:outline-none focus:ring-2 focus:ring-orange-300"
                />
              </div>

              {/* Visible toggle */}
              <div className="flex flex-col items-center gap-1">
                <label className="text-xs text-gray-500">Показувати</label>
                <button
                  onClick={() => updateItem(i, "visible", !item.visible)}
                  className={`w-10 h-6 rounded-full transition-colors relative ${item.visible ? "bg-orange-500" : "bg-gray-300"}`}
                >
                  <span
                    className="absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-all"
                    style={{ left: item.visible ? "22px" : "2px" }}
                  />
                </button>
              </div>

              {/* Remove */}
              <button
                onClick={() => removeItem(i)}
                className="text-red-400 hover:text-red-600 text-lg leading-none px-1"
                title="Видалити"
              >
                ×
              </button>
            </div>
          ))}
        </div>

        <button
          onClick={addItem}
          className="w-full py-2.5 rounded-xl border-2 border-dashed border-gray-200 text-sm text-gray-400 hover:border-orange-300 hover:text-orange-500 transition-colors"
        >
          + Додати пункт
        </button>

        {/* Preview */}
        <div className="border rounded-xl overflow-hidden">
          <div className="px-4 py-2 text-xs text-gray-500 bg-gray-50 border-b font-medium uppercase tracking-wider">
            Попередній перегляд навбару
          </div>
          <div
            className="flex items-center gap-1 px-6 overflow-x-auto"
            style={{ backgroundColor: settings["colors.navy"] ?? "#1a2744", height: "52px" }}
          >
            {items.filter((n) => n.visible).map((item, i) => (
              <span
                key={i}
                className="px-3 py-1.5 rounded text-sm font-medium whitespace-nowrap"
                style={{
                  color: i === 0 ? (settings["colors.orange"] ?? "#f97316") : "rgba(255,255,255,0.85)",
                  borderBottom: i === 0 ? `2px solid ${settings["colors.orange"] ?? "#f97316"}` : "none",
                }}
              >
                {item.label}
              </span>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={handleSave}
            disabled={pending}
            className="px-6 py-2.5 rounded-lg font-bold text-white text-sm disabled:opacity-60"
            style={{ backgroundColor: "#1a2744" }}
          >
            {pending ? "Зберігається..." : "Зберегти навігацію"}
          </button>
          {saved && <span className="text-green-600 text-sm font-medium">✓ Збережено!</span>}
        </div>
      </div>
    );
  }
);

export default NavButtonsTab;

structure.app/admin/site-editor/tabs/NewsTab.tsx:
"use client";

import { useState, useTransition, useRef } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { createNews, updateNews, deleteNews } from "@/actions/admin-data";
import type { NewsRow } from "../SiteEditorClient";

const CATEGORIES = ["news", "schedule", "results", "announcement"];
const CATEGORY_LABELS: Record<string, string> = {
  news: "Новина",
  schedule: "Розклад",
  results: "Результати",
  announcement: "Оголошення",
};

const EMPTY_FORM = { title: "", slug: "", content: "", category: "news", isPublished: true, imageUrl: "" };

function slugify(text: string) {
  return text
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/[^\w-]/g, "")
    .slice(0, 80);
}

export default function NewsTab({ news }: { news: NewsRow[] }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [form, setForm] = useState(EMPTY_FORM);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleEdit = (n: NewsRow) => {
    setEditingId(n.id);
    setForm({
      title: n.title,
      slug: n.slug,
      content: n.content,
      category: n.category ?? "news",
      isPublished: n.isPublished,
      imageUrl: n.imageUrl ?? "",
    });
    setShowForm(true);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      fd.append("type", "news");
      const res = await fetch("/api/upload", { method: "POST", body: fd });
      const data = await res.json();
      if (data.url) {
        setForm((f) => ({ ...f, imageUrl: data.url }));
      }
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const handleSave = () => {
    if (!form.title.trim()) return;
    const slug = form.slug.trim() || slugify(form.title);
    startTransition(async () => {
      try {
        if (editingId) {
          await updateNews(editingId, { ...form, slug });
        } else {
          await createNews({ ...form, slug });
        }
        setForm(EMPTY_FORM);
        setEditingId(null);
        setShowForm(false);
        router.refresh();
      } catch (err) {
        console.error("Помилка при збереженні новини:", err);
        alert("Помилка при збереженні новини. Спробуйте ще раз.");
      }
    });
  };

  const handleDelete = (id: number) => {
    if (!confirm("Видалити новину?")) return;
    startTransition(async () => {
      try {
        await deleteNews(id);
        router.refresh();
      } catch (err) {
        console.error("Помилка при видаленні новини:", err);
        alert("Помилка при видаленні новини. Спробуйте ще раз.");
      }
    });
  };

  return (
    <div className="space-y-5">
      <div className="flex justify-end">
        <button
          onClick={() => { setShowForm(true); setEditingId(null); setForm(EMPTY_FORM); }}
          className="px-4 py-2 rounded-lg text-sm font-bold text-white"
          style={{ backgroundColor: "#f97316" }}
        >
          + Додати новину
        </button>
      </div>

      {showForm && (
        <div className="bg-gray-50 border rounded-xl p-4 space-y-3">
          <h3 className="font-bold text-gray-700">{editingId ? "Редагувати новину" : "Нова новина"}</h3>

          {/* Title */}
          <div>
            <label className="text-xs text-gray-500 mb-1 block">Заголовок</label>
            <input
              className="w-full border rounded-lg px-3 py-2 text-sm"
              placeholder="Заголовок новини"
              value={form.title}
              onChange={(e) => setForm((f) => ({ ...f, title: e.target.value, slug: slugify(e.target.value) }))}
            />
          </div>

          {/* Slug */}
          <div>
            <label className="text-xs text-gray-500 mb-1 block">Slug (URL)</label>
            <input
              className="w-full border rounded-lg px-3 py-2 text-sm font-mono text-gray-600"
              value={form.slug}
              onChange={(e) => setForm((f) => ({ ...f, slug: slugify(e.target.value) }))}
            />
          </div>

          {/* Category + Published */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs text-gray-500 mb-1 block">Категорія</label>
              <select
                className="w-full border rounded-lg px-3 py-2 text-sm"
                value={form.category}
                onChange={(e) => setForm((f) => ({ ...f, category: e.target.value }))}
              >
                {CATEGORIES.map((c) => <option key={c} value={c}>{CATEGORY_LABELS[c]}</option>)}
              </select>
            </div>
            <div className="flex items-end pb-1">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={form.isPublished}
                  onChange={(e) => setForm((f) => ({ ...f, isPublished: e.target.checked }))}
                  className="w-4 h-4"
                />
                <span className="text-sm text-gray-700">Опублікувати</span>
              </label>
            </div>
          </div>

          {/* Image upload */}
          <div>
            <label className="text-xs text-gray-500 mb-1 block">Зображення новини</label>
            <div className="flex items-start gap-3">
              {/* Preview */}
              {form.imageUrl ? (
                <div className="relative w-32 h-20 rounded-lg overflow-hidden border bg-gray-100 flex-shrink-0">
                  <Image src={form.imageUrl} alt="preview" fill className="object-cover" />
                  <button
                    type="button"
                    onClick={() => setForm((f) => ({ ...f, imageUrl: "" }))}
                    className="absolute top-1 right-1 bg-black/60 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs hover:bg-black"
                  >
                    ×
                  </button>
                </div>
              ) : (
                <div className="w-32 h-20 rounded-lg border-2 border-dashed border-gray-300 flex items-center justify-center flex-shrink-0 bg-white">
                  <span className="text-gray-400 text-xs text-center">Немає фото</span>
                </div>
              )}

              {/* Upload button */}
              <div className="flex flex-col gap-2">
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={handleImageUpload}
                />
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={uploading}
                  className="px-4 py-2 rounded-lg text-sm font-medium border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50 transition-colors"
                >
                  {uploading ? "Завантаження..." : "Завантажити фото"}
                </button>
                {form.imageUrl && (
                  <p className="text-xs text-gray-400 break-all max-w-xs">{form.imageUrl}</p>
                )}
              </div>
            </div>
          </div>

          {/* Content */}
          <div>
            <label className="text-xs text-gray-500 mb-1 block">Текст новини</label>
            <textarea
              className="w-full border rounded-lg px-3 py-2 text-sm min-h-32"
              placeholder="Введіть текст новини..."
              value={form.content}
              onChange={(e) => setForm((f) => ({ ...f, content: e.target.value }))}
            />
          </div>

          {/* Buttons */}
          <div className="flex gap-2">
            <button
              onClick={handleSave}
              disabled={pending || uploading}
              className="px-4 py-2 rounded-lg text-sm font-bold text-white disabled:opacity-50"
              style={{ backgroundColor: "#1a2744" }}
            >
              {editingId ? "Зберегти" : "Опублікувати"}
            </button>
            <button
              onClick={() => { setShowForm(false); setEditingId(null); }}
              className="px-4 py-2 rounded-lg text-sm border text-gray-600"
            >
              Скасувати
            </button>
          </div>
        </div>
      )}

      {/* News list */}
      <div className="space-y-2">
        {news.length === 0 ? (
          <p className="text-gray-400 text-sm text-center py-8">Новин немає. Додайте першу!</p>
        ) : (
          news.map((n) => (
            <div key={n.id} className="bg-white border rounded-lg overflow-hidden">
              <div
                className="px-4 py-3 flex items-center justify-between cursor-pointer hover:bg-gray-50"
                onClick={() => setExpandedId(expandedId === n.id ? null : n.id)}
              >
                <div className="flex items-center gap-3 flex-1 min-w-0">
                  {n.imageUrl && (
                    <div className="relative w-10 h-10 rounded overflow-hidden flex-shrink-0">
                      <Image src={n.imageUrl} alt={n.title} fill className="object-cover" />
                    </div>
                  )}
                  <span
                    className="text-xs px-2 py-0.5 rounded-full text-white shrink-0"
                    style={{ backgroundColor: n.category === "schedule" ? "#3b82f6" : n.category === "results" ? "#10b981" : "#f97316" }}
                  >
                    {CATEGORY_LABELS[n.category ?? "news"] ?? n.category}
                  </span>
                  <span className="font-medium text-gray-800 text-sm truncate">{n.title}</span>
                  {!n.isPublished && (
                    <span className="text-xs text-gray-400 shrink-0">[чернетка]</span>
                  )}
                </div>
                <div className="flex items-center gap-2 ml-2 shrink-0">
                  <span className="text-xs text-gray-400">
                    {new Date(n.publishedAt).toLocaleDateString("uk-UA", { day: "numeric", month: "short" })}
                  </span>
                  <button onClick={(e) => { e.stopPropagation(); handleEdit(n); }} className="text-xs text-blue-500 hover:underline">Ред.</button>
                  <button onClick={(e) => { e.stopPropagation(); handleDelete(n.id); }} className="text-xs text-red-400 hover:underline">Вид.</button>
                </div>
              </div>
              {expandedId === n.id && (
                <div className="px-4 pb-3 text-sm text-gray-600 border-t bg-gray-50 whitespace-pre-wrap">
                  {n.content}
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

structure.app/admin/site-editor/tabs/ScheduleTab.t:
"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { createGame, updateGame, deleteGame } from "@/actions/admin-data";
import type { GameRow, TeamRow } from "../SiteEditorClient";

const STATUSES = ["SCHEDULED", "LIVE", "FINAL"];
const STATUS_LABELS: Record<string, string> = { SCHEDULED: "Заплановано", LIVE: "Live", FINAL: "Фінал" };
const STATUS_COLORS: Record<string, string> = { SCHEDULED: "#3b82f6", LIVE: "#ef4444", FINAL: "#6b7280" };

const EMPTY_FORM = {
  homeTeamId: "",
  awayTeamId: "",
  scheduledAt: "",
  status: "SCHEDULED",
  homeScore: "0",
  awayScore: "0",
};

type TeamRowWithAge = TeamRow & { ageGroup?: string };

export default function ScheduleTab({ games, teams }: { games: GameRow[]; teams: TeamRow[] }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [form, setForm] = useState(EMPTY_FORM);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [ageFilter, setAgeFilter] = useState<"younger" | "older">("younger");
  const [error, setError] = useState<string | null>(null);

  // Determine ageGroup of a game by its home team
  const teamAgeMap: Record<number, string> = {};
  (teams as TeamRowWithAge[]).forEach((t) => {
    teamAgeMap[t.id] = t.ageGroup ?? "younger";
  });

  const getGameAge = (g: GameRow) => teamAgeMap[g.homeTeamId] ?? teamAgeMap[g.awayTeamId] ?? "younger";

  const filteredGames = games.filter((g) => getGameAge(g) === ageFilter);
  const filteredTeams = (teams as TeamRowWithAge[]).filter((t) => (t.ageGroup ?? "younger") === ageFilter);

  const handleEdit = (g: GameRow) => {
    setEditingId(g.id);
    const dt = new Date(g.scheduledAt);
    const local = new Date(dt.getTime() - dt.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    setForm({
      homeTeamId: g.homeTeamId.toString(),
      awayTeamId: g.awayTeamId.toString(),
      scheduledAt: local,
      status: g.status,
      homeScore: g.homeScore.toString(),
      awayScore: g.awayScore.toString(),
    });
    setShowForm(true);
  };

  const handleSave = () => {
    setError(null);
    if (!form.homeTeamId || !form.awayTeamId || !form.scheduledAt) {
      setError("Заповніть обов'язкові поля: команди та дату");
      return;
    }
    const data = {
      homeTeamId: Number(form.homeTeamId),
      awayTeamId: Number(form.awayTeamId),
      scheduledAt: new Date(form.scheduledAt).toISOString(),
      status: form.status,
      homeScore: Number(form.homeScore),
      awayScore: Number(form.awayScore),
      ageGroup: ageFilter,
    };
    startTransition(async () => {
      try {
        if (editingId) {
          await updateGame(editingId, data);
        } else {
          await createGame(data);
        }
        setForm(EMPTY_FORM);
        setEditingId(null);
        setShowForm(false);
        setError(null);
        router.refresh();
      } catch (err) {
        const message = err instanceof Error ? err.message : "Невідома помилка при збереженні матчу";
        setError(message);
        console.error("Error saving game:", err);
      }
    });
  };

  const handleDelete = (id: number) => {
    if (!confirm("Видалити матч?")) return;
    setError(null);
    startTransition(async () => {
      try {
        await deleteGame(id);
        setError(null);
        router.refresh();
      } catch (err) {
        const message = err instanceof Error ? err.message : "Невідома помилка при видаленні матчу";
        setError(message);
        console.error("Error deleting game:", err);
      }
    });
  };

  const upcoming = filteredGames.filter((g: GameRow) => g.status !== "FINAL");
  const finished = filteredGames.filter((g: GameRow) => g.status === "FINAL");

  return (
    <div className="space-y-5">
      {/* Error message */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700 text-sm flex items-start justify-between">
          <div>
            <strong>⚠️ Помилка:</strong> {error}
          </div>
          <button
            onClick={() => setError(null)}
            className="text-red-500 hover:text-red-700 font-bold"
          >
            ✕
          </button>
        </div>
      )}

      {/* Age group switcher */}
      <div className="flex items-center justify-between">
        <div className="flex gap-2">
          <button
            onClick={() => { setAgeFilter("younger"); setShowForm(false); setForm(EMPTY_FORM); setEditingId(null); }}
            className={`px-5 py-2 rounded-lg font-bold text-sm transition-all ${
              ageFilter === "younger" ? "text-white shadow-md" : "bg-white border border-gray-200 text-gray-500 hover:border-gray-400"
            }`}
            style={ageFilter === "younger" ? { backgroundColor: "#f97316" } : {}}
          >
            U-14
          </button>
          <button
            onClick={() => { setAgeFilter("older"); setShowForm(false); setForm(EMPTY_FORM); setEditingId(null); }}
            className={`px-5 py-2 rounded-lg font-bold text-sm transition-all ${
              ageFilter === "older" ? "text-white shadow-md" : "bg-white border border-gray-200 text-gray-500 hover:border-gray-400"
            }`}
            style={ageFilter === "older" ? { backgroundColor: "#1a2744" } : {}}
          >
            U-16
          </button>
        </div>

        <button
          onClick={() => { setShowForm(true); setEditingId(null); setForm(EMPTY_FORM); }}
          className="px-4 py-2 rounded-lg text-sm font-bold text-white"
          style={{ backgroundColor: "#f97316" }}
        >
          + Додати матч
        </button>
      </div>

      {/* Form */}
      {showForm && (
        <div className="bg-gray-50 border rounded-xl p-4 space-y-3">
          <h3 className="font-bold text-gray-700">
            {editingId ? "Редагувати матч" : "Новий матч"}{" "}
            <span
              className="text-xs font-bold text-white px-2 py-0.5 rounded ml-1"
              style={{ backgroundColor: ageFilter === "older" ? "#1a2744" : "#f97316" }}
            >
              {ageFilter === "older" ? "U-16" : "U-14"}
            </span>
          </h3>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs text-gray-500 mb-1 block">Господарі</label>
              <select
                className="w-full border rounded-lg px-3 py-2 text-sm"
                value={form.homeTeamId}
                onChange={(e) => setForm((f) => ({ ...f, homeTeamId: e.target.value }))}
              >
                <option value="">Оберіть команду</option>
                {filteredTeams.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-gray-500 mb-1 block">Гості</label>
              <select
                className="w-full border rounded-lg px-3 py-2 text-sm"
                value={form.awayTeamId}
                onChange={(e) => setForm((f) => ({ ...f, awayTeamId: e.target.value }))}
              >
                <option value="">Оберіть команду</option>
                {filteredTeams.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-gray-500 mb-1 block">Дата та час</label>
              <input
                type="datetime-local"
                className="w-full border rounded-lg px-3 py-2 text-sm"
                value={form.scheduledAt}
                onChange={(e) => setForm((f) => ({ ...f, scheduledAt: e.target.value }))}
              />
            </div>
            <div>
              <label className="text-xs text-gray-500 mb-1 block">Статус</label>
              <select
                className="w-full border rounded-lg px-3 py-2 text-sm"
                value={form.status}
                onChange={(e) => setForm((f) => ({ ...f, status: e.target.value }))}
              >
                {STATUSES.map((s) => <option key={s} value={s}>{STATUS_LABELS[s]}</option>)}
              </select>
            </div>
            {form.status !== "SCHEDULED" && (
              <>
                <div>
                  <label className="text-xs text-gray-500 mb-1 block">Рахунок господарів</label>
                  <input
                    type="number"
                    className="w-full border rounded-lg px-3 py-2 text-sm"
                    value={form.homeScore}
                    onChange={(e) => setForm((f) => ({ ...f, homeScore: e.target.value }))}
                  />
                </div>
                <div>
                  <label className="text-xs text-gray-500 mb-1 block">Рахунок гостей</label>
                  <input
                    type="number"
                    className="w-full border rounded-lg px-3 py-2 text-sm"
                    value={form.awayScore}
                    onChange={(e) => setForm((f) => ({ ...f, awayScore: e.target.value }))}
                  />
                </div>
              </>
            )}
          </div>
          <div className="flex gap-2">
            <button
              onClick={handleSave}
              disabled={pending}
              className="px-4 py-2 rounded-lg text-sm font-bold text-white"
              style={{ backgroundColor: "#1a2744" }}
            >
              {editingId ? "Зберегти" : "Додати матч"}
            </button>
            <button
              onClick={() => { setShowForm(false); setEditingId(null); }}
              className="px-4 py-2 rounded-lg text-sm border text-gray-600"
            >
              Скасувати
            </button>
          </div>
        </div>
      )}

      {/* Upcoming */}
      <div>
        <h3 className="font-bold text-gray-700 mb-2">Заплановані матчі ({upcoming.length})</h3>
        {upcoming.length === 0 ? (
          <p className="text-gray-400 text-sm py-2">Немає запланованих матчів</p>
        ) : (
          <div className="space-y-2">
            {upcoming.map((g) => (
              <GameRowItem key={g.id} game={g} onEdit={handleEdit} onDelete={handleDelete} />
            ))}
          </div>
        )}
      </div>

      {/* Finished */}
      <div>
        <h3 className="font-bold text-gray-700 mb-2">Зіграні матчі ({finished.length})</h3>
        {finished.length === 0 ? (
          <p className="text-gray-400 text-sm py-2">Немає завершених матчів</p>
        ) : (
          <div className="space-y-2">
            {finished.map((g) => (
              <GameRowItem key={g.id} game={g} onEdit={handleEdit} onDelete={handleDelete} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function GameRowItem({ game, onEdit, onDelete }: { game: GameRow; onEdit: (g: GameRow) => void; onDelete: (id: number) => void }) {
  const date = new Date(game.scheduledAt);
  return (
    <div className="bg-white border rounded-lg px-4 py-3 flex items-center justify-between">
      <div className="flex items-center gap-3 flex-1">
        <div className="text-xs text-gray-400 w-20 shrink-0">
          {date.toLocaleDateString("uk-UA", { day: "numeric", month: "short" })}{" "}
          {date.toLocaleTimeString("uk-UA", { hour: "2-digit", minute: "2-digit" })}
        </div>
        <div className="font-medium text-gray-800 text-sm">
          {game.homeTeam.name} — {game.awayTeam.name}
        </div>
        {game.status !== "SCHEDULED" && (
          <div className="font-bold text-sm" style={{ color: "#1a2744" }}>
            {game.homeScore} : {game.awayScore}
          </div>
        )}
      </div>
      <div className="flex items-center gap-2">
        <span
          className="text-xs px-2 py-0.5 rounded-full text-white font-medium"
          style={{ backgroundColor: STATUS_COLORS[game.status] }}
        >
          {STATUS_LABELS[game.status]}
        </span>
        <button onClick={() => onEdit(game)} className="text-xs text-blue-500 hover:underline">Ред.</button>
        <button onClick={() => onDelete(game.id)} className="text-xs text-red-400 hover:underline">Вид.</button>
      </div>
    </div>
  );
}

structure.app/admin/site-editor/tabs/ShopTab.tsx:
"use client";

import { useState, useTransition, useRef } from "react";
import {
  createShopProduct,
  updateShopProduct,
  deleteShopProduct,
  type ShopProductInput,
} from "@/actions/admin-data";
import { updateSiteTexts } from "@/actions/site-settings";

const CATEGORIES = ["М'ячі", "Форма", "Взуття", "Захист", "Обладнання", "Аксесуари"];
const BADGES = ["", "ХІТ", "НОВІ", "ЗНИЖКА", "ОФІЦІЙНА", "РОЗПРОДАЖ"];

type Product = {
  id: number;
  name: string;
  description: string;
  price: number;
  oldPrice: number | null;
  category: string;
  emoji: string;
  badge: string | null;
  imageUrl: string | null;
  sizes: string | null;
  inStock: boolean;
  sortOrder: number;
  showInChat?: boolean;
  chatPriority?: boolean;
};

const EMPTY_FORM: ShopProductInput = {
  name: "",
  description: "",
  price: 0,
  oldPrice: null,
  category: "М'ячі",
  emoji: "🏀",
  badge: null,
  imageUrl: null,
  sizes: null,
  inStock: true,
  sortOrder: 0,
};

type TabSection = "products" | "settings" | "widget";

export default function ShopTab({
  products,
  settings,
}: {
  products: Product[];
  settings: Record<string, string>;
}) {
  const [section, setSection] = useState<TabSection>("products");
  const [pending, startTransition] = useTransition();
  const [form, setForm] = useState<ShopProductInput>(EMPTY_FORM);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [filterCat, setFilterCat] = useState("Всі");
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Settings state
  const [tgBotToken, setTgBotToken] = useState(settings["shop.tgBotToken"] ?? "");
  const [tgChatId, setTgChatId] = useState(settings["shop.tgChatId"] ?? "");
  const [cardNumber, setCardNumber] = useState(settings["donate.cardNumber"] ?? "4149510093172395");
  const [cardName, setCardName] = useState(settings["donate.cardName"] ?? "Христина Полякова");
  const [notifyEmail, setNotifyEmail] = useState(settings["shop.notifyEmail"] ?? "bclvivbasketball@gmail.com");
  const [gmailUser, setGmailUser] = useState(settings["shop.gmailUser"] ?? "");
  const [gmailPass, setGmailPass] = useState(settings["shop.gmailPass"] ?? "");
  const [settingsSaved, setSettingsSaved] = useState(false);

  // Widget state
  const [widgetEnabled, setWidgetEnabled] = useState(settings["widget.enabled"] !== "false");
  const [widgetInterval, setWidgetInterval] = useState(Number(settings["widget.interval"] || "20"));
  const [widgetMode, setWidgetMode] = useState(settings["widget.mode"] || "sequential");
  const [widgetSaved, setWidgetSaved] = useState(false);
  const [widgetPushingId, setWidgetPushingId] = useState<number | null>(null);
  const [widgetTogglingId, setWidgetTogglingId] = useState<number | null>(null);
  const [localProducts, setLocalProducts] = useState(products);

  const filtered = filterCat === "Всі" ? products : products.filter((p) => p.category === filterCat);

  const handleEdit = (p: Product) => {
    setEditingId(p.id);
    setForm({
      name: p.name,
      description: p.description,
      price: p.price,
      oldPrice: p.oldPrice,
      category: p.category,
      emoji: p.emoji,
      badge: p.badge,
      imageUrl: p.imageUrl,
      sizes: p.sizes,
      inStock: p.inStock,
      sortOrder: p.sortOrder,
    });
    setShowForm(true);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      fd.append("type", "shop");
      const res = await fetch("/api/upload", { method: "POST", body: fd });
      const data = await res.json();
      if (data.url) setForm((f) => ({ ...f, imageUrl: data.url }));
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const handleSave = () => {
    if (!form.name.trim() || form.price <= 0) return;
    startTransition(async () => {
      if (editingId) {
        await updateShopProduct(editingId, form);
      } else {
        await createShopProduct(form);
      }
      setForm(EMPTY_FORM);
      setEditingId(null);
      setShowForm(false);
    });
  };

  const handleDelete = (id: number) => {
    if (!confirm("Видалити товар?")) return;
    startTransition(async () => { await deleteShopProduct(id); });
  };

  const handleToggleStock = (p: Product) => {
    startTransition(async () => { await updateShopProduct(p.id, { inStock: !p.inStock }); });
  };

  const handleSaveSettings = () => {
    startTransition(async () => {
      await updateSiteTexts({
        "shop.tgBotToken": tgBotToken,
        "shop.tgChatId": tgChatId,
        "donate.cardNumber": cardNumber,
        "donate.cardName": cardName,
        "shop.notifyEmail": notifyEmail,
        "shop.gmailUser": gmailUser,
        "shop.gmailPass": gmailPass,
      });
      setSettingsSaved(true);
      setTimeout(() => setSettingsSaved(false), 2000);
    });
  };

  const handleSaveWidgetSettings = async () => {
    await fetch("/api/chat-widget/settings", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ enabled: widgetEnabled, interval: widgetInterval, mode: widgetMode }),
    });
    setWidgetSaved(true);
    setTimeout(() => setWidgetSaved(false), 2000);
  };

  const handleToggleShowInChat = async (p: Product) => {
    const newVal = !p.showInChat;
    setLocalProducts(prev => prev.map(x => x.id === p.id ? { ...x, showInChat: newVal } : x));
    setWidgetTogglingId(p.id);
    await fetch("/api/chat-widget/settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ productId: p.id, showInChat: newVal }),
    });
    setWidgetTogglingId(null);
  };

  const handleTogglePriority = async (p: Product) => {
    const newVal = !p.chatPriority;
    setLocalProducts(prev => prev.map(x => x.id === p.id ? { ...x, chatPriority: newVal } : x));
    setWidgetTogglingId(p.id);
    await fetch("/api/chat-widget/settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ productId: p.id, chatPriority: newVal }),
    });
    setWidgetTogglingId(null);
  };

  const handlePushNow = async (p: Product) => {
    setWidgetPushingId(p.id);
    await fetch("/api/chat-widget/push", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ productId: p.id }),
    });
    setWidgetPushingId(null);
  };

  const cats = ["Всі", ...CATEGORIES];

  return (
    <div className="space-y-5">
      {/* Section tabs */}
      <div className="flex gap-2 border-b pb-3">
        <button
          onClick={() => setSection("products")}
          className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${section === "products" ? "text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"}`}
          style={section === "products" ? { backgroundColor: "#1a2744" } : {}}
        >
          Товари
        </button>
        <button
          onClick={() => setSection("settings")}
          className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${section === "settings" ? "text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"}`}
          style={section === "settings" ? { backgroundColor: "#1a2744" } : {}}
        >
          Налаштування магазину
        </button>
        <button
          onClick={() => setSection("widget")}
          className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${section === "widget" ? "text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"}`}
          style={section === "widget" ? { backgroundColor: "#f46f10" } : {}}
        >
          Витрина в чаті
        </button>
      </div>

      {/* ===== SETTINGS SECTION ===== */}
      {section === "settings" && (
        <div className="space-y-5">
          {/* Telegram */}
          <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 space-y-3">
            <div className="flex items-center gap-2">
              <span className="text-xl">✈️</span>
              <h3 className="font-bold text-blue-800">Telegram сповіщення про замовлення</h3>
            </div>
            <p className="text-xs text-blue-600">
