                <div className="flex gap-1.5 mt-1.5 flex-wrap">
                  {["XS,S,M,L,XL,XXL", "S,M,L,XL", "36,37,38,39,40,41,42", "Один розмір"].map((preset) => (
                    <button
                      key={preset}
