                      onClick={() => setForm((f) => ({ ...f, sizes: preset }))}
                      className="text-xs px-2 py-0.5 rounded border border-gray-200 text-gray-500 hover:border-orange-400 hover:text-orange-500 bg-white"
                    >
                      {preset}
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-4 gap-3">
                <div>
                  <label className="text-xs text-gray-500 mb-1 block">Ціна (грн) *</label>
                  <input
                    type="number"
                    className="w-full border rounded-lg px-3 py-2 text-sm"
                    value={form.price || ""}
                    onChange={(e) => setForm((f) => ({ ...f, price: Number(e.target.value) }))}
                  />
                </div>
                <div>
                  <label className="text-xs text-gray-500 mb-1 block">Стара ціна</label>
                  <input
                    type="number"
                    className="w-full border rounded-lg px-3 py-2 text-sm"
                    placeholder="необов'язково"
                    value={form.oldPrice ?? ""}
                    onChange={(e) => setForm((f) => ({ ...f, oldPrice: e.target.value ? Number(e.target.value) : null }))}
                  />
                </div>
                <div>
                  <label className="text-xs text-gray-500 mb-1 block">Emoji</label>
                  <input
                    className="w-full border rounded-lg px-3 py-2 text-sm text-center text-xl"
                    value={form.emoji}
                    onChange={(e) => setForm((f) => ({ ...f, emoji: e.target.value }))}
                  />
                </div>
                <div>
                  <label className="text-xs text-gray-500 mb-1 block">Бейдж</label>
                  <select
                    className="w-full border rounded-lg px-3 py-2 text-sm"
                    value={form.badge ?? ""}
                    onChange={(e) => setForm((f) => ({ ...f, badge: e.target.value || null }))}
                  >
                    {BADGES.map((b) => <option key={b} value={b}>{b || "— немає —"}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3 items-end">
                <div>
                  <label className="text-xs text-gray-500 mb-1 block">Порядок сортування</label>
                  <input
                    type="number"
                    className="w-full border rounded-lg px-3 py-2 text-sm"
                    value={form.sortOrder}
                    onChange={(e) => setForm((f) => ({ ...f, sortOrder: Number(e.target.value) }))}
                  />
                </div>
                <div className="flex items-center gap-2 pb-2">
                  <input
                    type="checkbox"
                    id="inStock"
                    checked={form.inStock}
                    onChange={(e) => setForm((f) => ({ ...f, inStock: e.target.checked }))}
                    className="w-4 h-4"
                  />
                  <label htmlFor="inStock" className="text-sm text-gray-700 cursor-pointer">В наявності</label>
                </div>
              </div>

              <div>
                <label className="text-xs text-gray-500 mb-1 block">Фото товару</label>
                <div className="flex items-start gap-3">
                  {form.imageUrl ? (
                    <div className="relative w-24 h-24 rounded-lg overflow-hidden border bg-gray-100 flex-shrink-0">
                      <img src={form.imageUrl} alt="preview" className="w-full h-full object-cover" />
                      <button
                        type="button"
                        onClick={() => setForm((f) => ({ ...f, imageUrl: null }))}
                        className="absolute top-1 right-1 bg-black/60 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs hover:bg-black"
                      >×</button>
                    </div>
                  ) : (
                    <div className="w-24 h-24 rounded-lg border-2 border-dashed border-gray-300 flex items-center justify-center flex-shrink-0 bg-white text-4xl">
                      {form.emoji}
                    </div>
                  )}
                  <div className="flex flex-col gap-2">
                    <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
                    <button
                      type="button"
                      onClick={() => fileInputRef.current?.click()}
                      disabled={uploading}
                      className="px-4 py-2 rounded-lg text-sm font-medium border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50"
                    >
                      {uploading ? "Завантаження..." : "Завантажити фото"}
                    </button>
                  </div>
                </div>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={handleSave}
                  disabled={pending || uploading || !form.name.trim() || form.price <= 0}
                  className="px-4 py-2 rounded-lg text-sm font-bold text-white disabled:opacity-50"
                  style={{ backgroundColor: "#1a2744" }}
                >
                  {editingId ? "Зберегти" : "Додати товар"}
                </button>
                <button
                  onClick={() => { setShowForm(false); setEditingId(null); }}
                  className="px-4 py-2 rounded-lg text-sm border text-gray-600"
                >
                  Скасувати
                </button>
              </div>
            </div>
          )}

          <div className="flex gap-2 flex-wrap">
            {cats.map((c) => (
              <button
                key={c}
                onClick={() => setFilterCat(c)}
                className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${filterCat === c ? "text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"}`}
                style={filterCat === c ? { backgroundColor: "#f97316" } : {}}
              >
                {c}
              </button>
            ))}
            <span className="ml-auto text-xs text-gray-400 self-center">{filtered.length} товарів</span>
          </div>

          <div className="space-y-2">
            {filtered.length === 0 ? (
              <p className="text-gray-400 text-sm text-center py-8">Товарів немає. Додайте перший!</p>
            ) : (
              filtered.map((p) => (
                <div key={p.id} className={`bg-white border rounded-xl flex items-center gap-3 px-4 py-3 ${!p.inStock ? "opacity-60" : ""}`}>
                  <div className="w-12 h-12 rounded-lg overflow-hidden bg-gray-100 flex-shrink-0 flex items-center justify-center text-2xl">
                    {p.imageUrl ? <img src={p.imageUrl} alt={p.name} className="w-full h-full object-cover" /> : p.emoji}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-medium text-gray-800 text-sm truncate">{p.name}</span>
                      {p.badge && <span className="text-xs px-2 py-0.5 rounded text-white font-bold" style={{ backgroundColor: "#f97316" }}>{p.badge}</span>}
                      {!p.inStock && <span className="text-xs px-2 py-0.5 rounded bg-gray-200 text-gray-500 font-medium">Немає</span>}
                    </div>
                    <div className="flex items-center gap-3 mt-0.5">
                      <span className="text-xs text-gray-400">{p.category}</span>
                      <span className="font-bold text-orange-500 text-sm">{p.price} грн</span>
                      {p.sizes && <span className="text-xs text-blue-500">📏 {p.sizes}</span>}
                      {p.oldPrice && <span className="text-xs text-gray-400 line-through">{p.oldPrice} грн</span>}
                    </div>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    <button
                      onClick={() => handleToggleStock(p)}
                      disabled={pending}
                      className={`text-xs px-2 py-1 rounded border transition-colors ${p.inStock ? "border-green-200 text-green-600 hover:bg-green-50" : "border-gray-300 text-gray-500 hover:bg-gray-50"}`}
                    >
                      {p.inStock ? "В наявності" : "Немає"}
                    </button>
                    <button onClick={() => handleEdit(p)} className="text-xs text-blue-500 hover:underline">Ред.</button>
                    <button onClick={() => handleDelete(p.id)} className="text-xs text-red-400 hover:underline">Вид.</button>
                  </div>
                </div>
              ))
            )}
          </div>
        </>
      )}
    </div>
  );
}

structure.app/admin/site-editor/tabs/StandingsMana:
"use client";
import { useState, useEffect } from "react";

type AgeGroup = "younger" | "older";

type Standing = {
  id: number;
  teamId: number;
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsFor: number;
  pointsAgainst: number;
  team?: { name: string };
};

type EditState = {
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsFor: number;
  pointsAgainst: number;
};

const fields: { key: keyof EditState; label: string }[] = [
  { key: "gamesPlayed", label: "І" },
  { key: "wins", label: "П" },
  { key: "losses", label: "ПР" },
  { key: "pointsFor", label: "+" },
  { key: "pointsAgainst", label: "-" },
];

export default function StandingsManageTab() {
  const [ag, setAg] = useState<AgeGroup>("younger");
  const [standings, setStandings] = useState<Standing[]>([]);
  const [loading, setLoading] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editValues, setEditValues] = useState<EditState | null>(null);
  const [saving, setSaving] = useState(false);

  const load = () => {
    setLoading(true);
    fetch(`/api/standings?ag=${ag}`)
      .then(r => r.json())
      .then(d => { setStandings(Array.isArray(d) ? d : []); setLoading(false); });
  };

  useEffect(() => {
    setEditingId(null);
    setEditValues(null);
    load();
  }, [ag]);

  const startEdit = (st: Standing) => {
    setEditingId(st.id);
    setEditValues({
      gamesPlayed: st.gamesPlayed,
      wins: st.wins,
      losses: st.losses,
      pointsFor: st.pointsFor,
      pointsAgainst: st.pointsAgainst,
    });
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditValues(null);
  };

  const save = async (standingId: number) => {
    if (!editValues) return;
    setSaving(true);
    await fetch("/api/admin/standings/update", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ standingId, ...editValues }),
    });
    setSaving(false);
    setEditingId(null);
    setEditValues(null);
    load();
  };

  const resetAll = async () => {
    if (!confirm(`Обнулити всю таблицю для ${ag === "younger" ? "U-14" : "U-16"}?`)) return;
    await fetch("/api/admin/standings/reset", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ag }),
    });
    cancelEdit();
    load();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-black" style={{ color: "#1a2744" }}>🏆 Таблиця змагань</h2>
        <div className="flex gap-2 items-center">
          {(["younger", "older"] as AgeGroup[]).map(g => (
            <button key={g} onClick={() => setAg(g)}
              className="px-3 py-1 rounded-full text-sm font-bold"
              style={{ background: ag === g ? "#f97316" : "#f1f5f9", color: ag === g ? "white" : "#64748b" }}>
              {g === "younger" ? "U-14" : "U-16"}
            </button>
          ))}
          <button onClick={resetAll}
            className="px-3 py-1 rounded-full text-sm font-bold bg-red-100 text-red-600 hover:bg-red-200">
            🗑 Обнулити все
          </button>
        </div>
      </div>

      <div className="overflow-x-auto rounded-xl border border-gray-100">
        <table className="w-full text-sm">
          <thead>
            <tr style={{ background: "#1a2744", color: "white" }}>
              <th className="px-3 py-2 text-left">Команда</th>
              {fields.map(f => <th key={f.key} className="px-2 py-2 text-center">{f.label}</th>)}
              <th className="px-2 py-2 text-center">Дії</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={7} className="text-center py-8 text-gray-400">Завантаження...</td></tr>
            ) : standings.length === 0 ? (
              <tr><td colSpan={7} className="text-center py-8 text-gray-400">Немає даних</td></tr>
            ) : standings.map((st, i) => {
              const isEditing = editingId === st.id;
              return (
                <tr key={st.id} style={{ background: i % 2 === 0 ? "#f8fafc" : "white" }}>
                  <td className="px-3 py-2 font-medium">{st.team?.name ?? `Команда ${st.teamId}`}</td>
                  {fields.map(f => (
                    <td key={f.key} className="px-2 py-1 text-center">
                      {isEditing && editValues ? (
                        <input
                          type="number"
                          min={0}
                          value={editValues[f.key]}
                          onChange={e => setEditValues(prev => prev ? { ...prev, [f.key]: Math.max(0, parseInt(e.target.value) || 0) } : prev)}
                          className="w-14 text-center border border-orange-300 rounded px-1 py-0.5 text-sm font-bold focus:outline-none focus:ring-1 focus:ring-orange-400"
                        />
                      ) : (
                        <span className="font-bold">{st[f.key] ?? 0}</span>
                      )}
                    </td>
                  ))}
                  <td className="px-2 py-1 text-center">
                    {isEditing ? (
                      <div className="flex gap-1 justify-center">
                        <button
                          onClick={() => save(st.id)}
                          disabled={saving}
                          className="px-2 py-1 rounded text-xs font-bold bg-green-500 text-white hover:bg-green-600 disabled:opacity-50">
                          {saving ? "..." : "Зберегти"}
                        </button>
                        <button
                          onClick={cancelEdit}
                          className="px-2 py-1 rounded text-xs font-bold bg-gray-200 text-gray-600 hover:bg-gray-300">
                          Скасувати
                        </button>
                      </div>
                    ) : (
                      <button
                        onClick={() => startEdit(st)}
                        className="px-2 py-1 rounded text-xs font-bold bg-blue-100 text-blue-700 hover:bg-blue-200">
                        Редагувати
                      </button>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

