structure.app/admin/site-editor/tabs/VideosTab.tsx:
"use client";

import { useState, useEffect, useRef, useTransition } from "react";

type VideoItem = {
  id: number;
  title: string;
  url: string;
  thumbnail: string | null;
  type: string;
  publishedAt: string;
};

const VIDEO_TYPES = [
  { value: "highlights", label: "Хайлайти" },
  { value: "full", label: "Повний матч" },
  { value: "moments", label: "Кращі моменти" },
];

export default function VideosTab() {
  const [videos, setVideos] = useState<VideoItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("highlights");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);
  const [, startTransition] = useTransition();

  useEffect(() => {
    fetch("/api/videos")
      .then((r) => r.json())
      .then((d) => setVideos(d.videos ?? []))
      .finally(() => setLoading(false));
  }, []);

  async function handleUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!title.trim()) { setError("Введіть назву відео"); return; }
    setError("");
    setUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      fd.append("title", title.trim());
      fd.append("type", type);
      const res = await fetch("/api/videos", { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok) { setError(data.error || "Помилка завантаження"); return; }
      setVideos((v) => [data, ...v]);
      setTitle("");
      setSuccess("Відео завантажено!");
      setTimeout(() => setSuccess(""), 2500);
    } finally {
      setUploading(false);
      if (fileRef.current) fileRef.current.value = "";
    }
  }

  function handleDelete(id: number) {
    if (!confirm("Видалити відео?")) return;
    startTransition(async () => {
      const res = await fetch("/api/videos", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id }) });
      if (res.ok) setVideos((v) => v.filter((x) => x.id !== id));
    });
  }

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-base font-semibold text-gray-800">Відео-медіа</h3>
        <p className="text-sm text-gray-500 mt-0.5">Завантажуйте відео — вони з&apos;являться в розділі &quot;Медіа&quot; на сайті.</p>
      </div>

      {/* Upload form */}
      <div className="bg-gray-50 rounded-xl p-4 border space-y-3">
        <h4 className="font-bold text-gray-700 text-sm">Додати відео</h4>
        <div className="flex gap-3 flex-wrap items-end">
          <div className="flex-1 min-w-48">
            <label className="text-xs text-gray-500 mb-1 block">Назва</label>
            <input
              className="w-full border rounded-lg px-3 py-2 text-sm"
              placeholder="Хайлайти матчу..."
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
          </div>
          <div className="w-40">
            <label className="text-xs text-gray-500 mb-1 block">Тип</label>
            <select
              className="w-full border rounded-lg px-3 py-2 text-sm"
              value={type}
              onChange={(e) => setType(e.target.value)}
            >
              {VIDEO_TYPES.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
            </select>
          </div>
          <div>
            <input ref={fileRef} type="file" accept="video/*" className="hidden" onChange={handleUpload} />
            <button
              onClick={() => { if (!title.trim()) { setError("Введіть назву відео"); return; } fileRef.current?.click(); }}
              disabled={uploading}
              className="px-5 py-2 rounded-lg text-sm font-bold text-white disabled:opacity-50"
              style={{ backgroundColor: "#f97316" }}
            >
              {uploading ? "Завантаження..." : "Обрати відео"}
            </button>
          </div>
        </div>
        {error && <div className="text-xs text-red-500">{error}</div>}
        {success && <div className="text-xs text-green-600 font-medium">{success}</div>}
      </div>

      {/* Videos list */}
      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm">Завантаження...</div>
      ) : videos.length === 0 ? (
        <div className="text-center py-8 text-gray-400 text-sm border-2 border-dashed border-gray-200 rounded-xl">
          Відео ще не завантажені
        </div>
      ) : (
        <div className="space-y-3">
          {videos.map((v) => (
            <div key={v.id} className="flex items-center gap-4 bg-white rounded-xl border p-3">
              <div className="w-20 h-14 rounded-lg bg-gray-900 flex items-center justify-center flex-shrink-0 overflow-hidden">
                <video src={v.url} className="w-full h-full object-cover" muted />
              </div>
              <div className="flex-1 min-w-0">
                <div className="font-bold text-sm text-gray-800 truncate">{v.title}</div>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-xs text-orange-600 font-medium bg-orange-50 px-2 py-0.5 rounded">
                    {VIDEO_TYPES.find((t) => t.value === v.type)?.label ?? v.type}
                  </span>
                  <span className="text-xs text-gray-400">
                    {new Date(v.publishedAt).toLocaleDateString("uk-UA")}
                  </span>
                </div>
              </div>
              <button
                onClick={() => handleDelete(v.id)}
                className="text-xs px-2 py-1 rounded border border-red-200 text-red-500 hover:bg-red-50 flex-shrink-0"
              >
                Вид.
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

structure.app/admin/site-editor/tabs/WidgetsTab.ts:
"use client";

import { useState, useTransition, forwardRef, useImperativeHandle } from "react";
import { updateHomeWidgets } from "@/actions/site-settings";
import type { SaveHandle } from "../SiteEditorClient";

const WidgetsTab = forwardRef<SaveHandle, { settings: Record<string, string> }>(
  function WidgetsTab({ settings }, ref) {
  const [pending, startTransition] = useTransition();
  const [saved, setSaved] = useState(false);

  const [showLive, setShowLive] = useState(settings["home.showLive"] !== "false");
  const [showStandings, setShowStandings] = useState(settings["home.showStandings"] !== "false");
  const [showNews, setShowNews] = useState(settings["home.showNews"] !== "false");
  const [liveLimit, setLiveLimit] = useState(parseInt(settings["home.liveLimit"] ?? "4", 10));
  const [standingsLimit, setStandingsLimit] = useState(parseInt(settings["home.standingsLimit"] ?? "6", 10));
  const [newsLimit, setNewsLimit] = useState(parseInt(settings["home.newsLimit"] ?? "3", 10));
  const [liveTitle, setLiveTitle] = useState(settings["home.liveTitle"] ?? "Найближчі матчі");
  const [standingsTitle, setStandingsTitle] = useState(settings["home.standingsTitle"] ?? "Таблиця сезону");
  const [newsTitle, setNewsTitle] = useState(settings["home.newsTitle"] ?? "Останні новини");

  const handleSave = () => {
    startTransition(async () => {
      await updateHomeWidgets({
        "home.showLive": String(showLive),
        "home.showStandings": String(showStandings),
        "home.showNews": String(showNews),
        "home.liveLimit": String(liveLimit),
        "home.standingsLimit": String(standingsLimit),
        "home.newsLimit": String(newsLimit),
        "home.liveTitle": liveTitle,
        "home.standingsTitle": standingsTitle,
        "home.newsTitle": newsTitle,
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    });
  };

  useImperativeHandle(ref, () => ({ save: handleSave }));

  const Toggle = ({
    label,
    value,
    onChange,
  }: {
    label: string;
    value: boolean;
    onChange: (v: boolean) => void;
  }) => (
    <label className="flex items-center gap-3 cursor-pointer select-none">
      <div
        className={`relative w-10 h-6 rounded-full transition-colors ${value ? "bg-orange-500" : "bg-gray-300"}`}
        onClick={() => onChange(!value)}
      >
        <div
          className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-transform ${value ? "translate-x-5" : "translate-x-1"}`}
        />
      </div>
      <span className="text-sm font-medium text-gray-700">{label}</span>
    </label>
  );

  const WidgetRow = ({
    label,
    visible,
    onVisibleChange,
    limit,
    onLimitChange,
    title,
    onTitleChange,
    maxItems,
  }: {
    label: string;
    visible: boolean;
    onVisibleChange: (v: boolean) => void;
    limit: number;
    onLimitChange: (v: number) => void;
    title: string;
    onTitleChange: (v: string) => void;
    maxItems: number;
  }) => (
    <div className={`bg-gray-50 rounded-xl p-4 space-y-3 transition-opacity ${!visible ? "opacity-50" : ""}`}>
      <Toggle label={label} value={visible} onChange={onVisibleChange} />
      {visible && (
        <>
          <div className="flex items-center gap-4 pl-12">
            <div className="flex-1">
              <label className="block text-xs text-gray-500 mb-1">Заголовок секції</label>
              <input
                type="text"
                value={title}
                onChange={(e) => onTitleChange(e.target.value)}
                className="w-full border border-gray-200 rounded-lg px-3 py-1.5 text-sm focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-xs text-gray-500 mb-1">
                Кількість елементів: <span className="text-orange-500 font-bold">{limit}</span>
              </label>
              <input
                type="range"
                min={1}
                max={maxItems}
                value={limit}
                onChange={(e) => onLimitChange(parseInt(e.target.value))}
                className="w-32"
              />
            </div>
          </div>
        </>
      )}
    </div>
  );

  return (
    <div className="space-y-4">
      <p className="text-sm text-gray-500">
        Управляйте блоками на головній сторінці — вмикайте/вимикайте, налаштовуйте кількість елементів та заголовки.
      </p>

      <WidgetRow
        label="Live матчі та найближчі матчі"
        visible={showLive}
        onVisibleChange={setShowLive}
        limit={liveLimit}
        onLimitChange={setLiveLimit}
        title={liveTitle}
        onTitleChange={setLiveTitle}
        maxItems={8}
      />

      <WidgetRow
        label="Таблиця standings"
        visible={showStandings}
        onVisibleChange={setShowStandings}
        limit={standingsLimit}
        onLimitChange={setStandingsLimit}
        title={standingsTitle}
        onTitleChange={setStandingsTitle}
        maxItems={16}
      />

      <WidgetRow
        label="Останні новини"
        visible={showNews}
        onVisibleChange={setShowNews}
        limit={newsLimit}
        onLimitChange={setNewsLimit}
        title={newsTitle}
        onTitleChange={setNewsTitle}
        maxItems={9}
      />

      <div className="flex items-center gap-4 pt-2">
        <button
          onClick={handleSave}
          disabled={pending}
          className="px-6 py-2.5 rounded-lg font-bold text-white text-sm disabled:opacity-60"
          style={{ backgroundColor: "#1a2744" }}
        >
          {pending ? "Зберігається..." : "Зберегти налаштування"}
        </button>
        {saved && <span className="text-green-600 text-sm font-medium">✓ Збережено!</span>}
      </div>
    </div>
  );
}
);

export default WidgetsTab;

structure.app/admin/vip-requests/page.tsx:
'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';

interface VIPRequest {
  id: number;
  phone: string;
  firstName: string;
  lastName: string;
  role: string;
  createdAt: string;
}

export default function VIPRequestsPage() {
  const [requests, setRequests] = useState<VIPRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [activatingId, setActivatingId] = useState<number | null>(null);

  useEffect(() => {
    fetchRequests();
  }, []);

  const fetchRequests = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/admin/vip-requests');
      const data = await response.json();
      setRequests(data.requests || []);
    } catch (error) {
      console.error('Failed to fetch VIP requests:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleActivate = async (userId: number) => {
    if (!window.confirm('Підтвердити активацію VIP?')) return;

    try {
      setActivatingId(userId);
      const response = await fetch('/api/admin/vip-activate-manual', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, plan: 'month' }),
      });

      const data = await response.json();

      if (response.ok) {
        alert(`✅ VIP активовано для ${data.user.name}`);
        fetchRequests();
      } else {
        alert(`❌ Помилка: ${data.error || 'Невідома помилка'}`);
      }
    } catch (error) {
      console.error('Activation error:', error);
      alert('❌ Помилка активації');
    } finally {
      setActivatingId(null);
    }
  };

  const handleDeactivate = async (userId: number) => {
    if (!window.confirm('Повністю деактивувати VIP?')) return;

    try {
      setActivatingId(userId);
      const response = await fetch('/api/admin/vip-deactivate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId }),
      });

      const data = await response.json();

      if (response.ok) {
        alert('✅ VIP деактивовано');
        fetchRequests();
      } else {
        alert(`❌ Помилка: ${data.error}`);
      }
    } catch (error) {
      console.error('Deactivation error:', error);
      alert('❌ Помилка деактивації');
    } finally {
      setActivatingId(null);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  const pendingCount = requests.filter((r) => r.role === 'parent').length;
  const activeCount = requests.filter((r) => r.role === 'vip').length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">👑 VIP Заявки</h1>
          <p className="text-gray-600 mt-1">Управління заявками на активацію VIP</p>
        </div>
        <div className="flex gap-4">
          <Link
            href="/admin/dashboard"
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            ← Назад до дашборду
          </Link>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white rounded-lg shadow p-4">
          <div className="text-sm font-medium text-gray-600">Всього заявок</div>
          <div className="text-3xl font-bold text-blue-600 mt-2">{requests.length}</div>
        </div>
        <div className="bg-white rounded-lg shadow p-4">
          <div className="text-sm font-medium text-gray-600">⏳ Очікують активації</div>
          <div className="text-3xl font-bold text-yellow-600 mt-2">{pendingCount}</div>
        </div>
        <div className="bg-white rounded-lg shadow p-4">
          <div className="text-sm font-medium text-gray-600">✅ Активні</div>
          <div className="text-3xl font-bold text-green-600 mt-2">{activeCount}</div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                ID
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Батько
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Телефон
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Статус
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Дійсна до
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Дія
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {requests.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-6 py-8 text-center text-gray-500">
                  Немає заявок на VIP
                </td>
              </tr>
            ) : (
