    } catch (blobErr) {
      const errMsg = blobErr instanceof Error ? blobErr.message : String(blobErr);
      console.error(`[marketplace-upload ${uploadId}] Vercel Blob error: ${errMsg}`);
      return NextResponse.json({ error: `Blob error: ${errMsg}` }, { status: 500 });
    }
  } catch (e) {
    const errMsg = e instanceof Error ? e.message : String(e);
    console.error(`[marketplace-upload] Unexpected error: ${errMsg}`);
    return NextResponse.json({ error: "Upload failed" }, { status: 500 });
  }
}

