import type { GameEvent, Player, Team } from "@prisma/client";

type EventWithDetails = GameEvent & {
  player: (Pick<Player, "firstName" | "lastName" | "number">) | null;
};

interface Props {
  events: EventWithDetails[];
  homeTeam: Pick<Team, "id" | "name">;
  awayTeam: Pick<Team, "id" | "name">;
  homeScore: number;
  awayScore: number;
}

export default function ActionLog({ events, homeTeam, awayTeam }: Props) {
  return (
    <div className="bg-white rounded-xl shadow overflow-hidden">
      <div
        className="px-4 py-3 text-white font-bold text-sm"
        style={{ backgroundColor: "#1a2744" }}
      >
        Action Log
      </div>
      <div className="divide-y max-h-72 overflow-y-auto">
        {events.length === 0 && (
          <div className="px-4 py-6 text-center text-gray-400 text-sm">
            Подій поки немає
          </div>
        )}
        {events.map((event) => {
          const teamName =
            event.teamId === homeTeam.id ? homeTeam.name : awayTeam.name;

          return (
            <div key={event.id} className="px-4 py-2.5 flex items-center gap-3 text-sm hover:bg-gray-50">
              <span className="text-xs text-gray-400 w-6 flex-shrink-0">Q{event.quarter}</span>

              {event.type === "POINTS" && (
                <span
                  className="font-bold text-white text-xs px-1.5 py-0.5 rounded flex-shrink-0"
                  style={{
                    backgroundColor:
                      event.points === 3 ? "#1a2744" : event.points === 2 ? "#f97316" : "#3b82f6",
                  }}
                >
                  +{event.points}
                </span>
              )}
              {event.type === "FOUL" && (
                <span className="bg-red-100 text-red-600 text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                  ФОЛ
                </span>
              )}
              {event.type === "TIMEOUT" && (
                <span className="bg-yellow-100 text-yellow-700 text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                  ТАЙМ
                </span>
              )}
              {event.type === "QUARTER_END" && (
                <span className="bg-gray-100 text-gray-600 text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                  КІНЕЦЬ
                </span>
              )}
              {event.type === "REBOUND" && (
                <span className="bg-slate-100 text-slate-600 text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                  ПДБ
                </span>
              )}
              {event.type === "ASSIST" && (
                <span className="bg-green-100 text-green-600 text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                  ПЕР
                </span>
              )}
              {event.type === "STEAL" && (
                <span className="bg-purple-100 text-purple-600 text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                  ПРХ
                </span>
              )}
              {event.type === "BLOCK" && (
                <span className="bg-amber-100 text-amber-600 text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                  БЛК
                </span>
              )}

              <span className="text-gray-600 min-w-0 truncate">
                {event.player && (
                  <span className="font-medium text-gray-800">
                    #{event.player.number} {event.player.lastName}{" "}
                  </span>
                )}
                <span className="text-gray-400 text-xs">({teamName})</span>
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

structure.components/live-tracker/LiveScoreTracker:
"use client";

import { useState, useTransition, useEffect, useRef, useCallback } from "react";
import { nextQuarter, endGame, startGame, undoLastEvent } from "@/actions/game";
import ActionButtons from "./ActionButtons";
import ActionLog from "./ActionLog";
import type { Game, Team, Player, GameEvent } from "@prisma/client";

type GameWithAll = Game & {
  homeTeam: Team & { players: Player[] };
  awayTeam: Team & { players: Player[] };
  events: (GameEvent & {
    player: Pick<Player, "firstName" | "lastName" | "number"> | null;
  })[];
};

const QUARTER_DURATION = 10 * 60; // 600 seconds

function formatTime(seconds: number) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

export default function LiveScoreTracker({ game, btnBlue, btnOrange, btnNavy, btnRed }: {
  game: GameWithAll;
  btnBlue?: string;
  btnOrange?: string;
  btnNavy?: string;
  btnRed?: string;
}) {
  const [activeTeamId, setActiveTeamId] = useState<number>(game.homeTeamId);
  const [selectedPlayerId, setSelectedPlayerId] = useState<number | null>(null);
  const [pending, startTransition] = useTransition();

  // Timer state
  const [timeLeft, setTimeLeft] = useState(QUARTER_DURATION);
  const [timerRunning, setTimerRunning] = useState(false);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const quarterRef = useRef(game.quarter);

  // Reset timer when quarter changes
  useEffect(() => {
    if (quarterRef.current !== game.quarter) {
      quarterRef.current = game.quarter;
      setTimeLeft(QUARTER_DURATION);
      setTimerRunning(false);
    }
  }, [game.quarter]);

  const stopTimer = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setTimerRunning(false);
  }, []);

  const startTimer = useCallback(() => {
    if (intervalRef.current) return;
    setTimerRunning(true);
    intervalRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          stopTimer();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  }, [stopTimer]);

  useEffect(() => {
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, []);

  const isLive = game.status === "LIVE";
  const isScheduled = game.status === "SCHEDULED";

  const activePlayers =
    activeTeamId === game.homeTeamId ? game.homeTeam.players : game.awayTeam.players;

  const handleTeamSelect = (teamId: number) => {
    setActiveTeamId(teamId);
    setSelectedPlayerId(null);
  };

  const handleNextQuarter = () => {
    stopTimer();
    setTimeLeft(QUARTER_DURATION);
    startTransition(() => nextQuarter(game.id));
  };

  return (
    <div className="space-y-6">
      {/* Scoreboard */}
      <div className="bg-white rounded-xl shadow overflow-hidden">
        <div
          className="px-6 py-3 flex items-center justify-between text-white text-sm"
          style={{ backgroundColor: "#1a2744" }}
        >
          <span className="font-bold">
            {isLive ? `LIVE — Q${game.quarter}` : isScheduled ? "Заплановано" : "ФІНАЛ"}
          </span>
          <div className="flex gap-2">
            {isLive && game.quarter < 4 && (
              <button
                onClick={handleNextQuarter}
                disabled={pending}
                className="bg-white/20 hover:bg-white/30 text-white text-xs px-3 py-1 rounded-lg transition-colors disabled:opacity-50"
              >
                Наступна чверть →
              </button>
            )}
            {isScheduled && (
              <button
                onClick={() => startTransition(() => startGame(game.id))}
                disabled={pending}
                className="bg-green-500 hover:bg-green-600 text-white text-xs px-3 py-1 rounded-lg font-bold transition-colors disabled:opacity-50"
              >
                Почати матч
              </button>
            )}
            {isLive && (
              <button
                onClick={() => {
                  if (confirm("Завершити матч?")) {
                    stopTimer();
                    startTransition(() => endGame(game.id));
                  }
                }}
                disabled={pending}
                className="bg-red-500 hover:bg-red-600 text-white text-xs px-3 py-1 rounded-lg font-bold transition-colors disabled:opacity-50"
              >
                Завершити матч
              </button>
            )}
          </div>
        </div>

        <div className="p-6">
          <div className="flex items-center justify-between gap-4">
            <div className="flex-1 text-center">
              <div className="font-black text-lg text-gray-800">{game.homeTeam.name}</div>
            </div>
            <div className="text-center">
              <div className="text-5xl font-black" style={{ color: "#1a2744" }}>
                {game.homeScore} : {game.awayScore}
              </div>
            </div>
            <div className="flex-1 text-center">
              <div className="font-black text-lg text-gray-800">{game.awayTeam.name}</div>
            </div>
          </div>

          {/* Timer */}
          {isLive && (
            <div className="mt-4 flex items-center justify-center gap-4">
              <span
                className="text-3xl font-mono font-black tabular-nums"
                style={{ color: timeLeft === 0 ? "#ef4444" : "#1a2744" }}
              >
                {formatTime(timeLeft)}
              </span>
              <div className="flex gap-2">
                {!timerRunning ? (
                  <button
                    onClick={startTimer}
                    disabled={timeLeft === 0}
                    className="bg-green-500 hover:bg-green-600 text-white text-xs px-3 py-1.5 rounded-lg font-bold transition-colors disabled:opacity-40"
                  >
                    ▶ Старт
                  </button>
                ) : (
                  <button
                    onClick={stopTimer}
                    className="bg-yellow-500 hover:bg-yellow-600 text-white text-xs px-3 py-1.5 rounded-lg font-bold transition-colors"
                  >
                    ⏸ Пауза
                  </button>
                )}
                <button
                  onClick={() => { stopTimer(); setTimeLeft(QUARTER_DURATION); }}
                  className="bg-gray-200 hover:bg-gray-300 text-gray-700 text-xs px-3 py-1.5 rounded-lg font-bold transition-colors"
                >
                  ↺ Скинути
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      {isLive && (
        <>
          {/* Team selector */}
          <div>
            <div className="text-xs text-gray-500 uppercase tracking-wider mb-2 font-semibold">
              Активна команда:
            </div>
            <div className="grid grid-cols-2 gap-3">
              {[game.homeTeam, game.awayTeam].map((team) => (
                <button
                  key={team.id}
                  onClick={() => handleTeamSelect(team.id)}
                  className={`py-3 px-4 rounded-xl font-bold text-sm transition-all border-2 ${
                    activeTeamId === team.id
                      ? "text-white border-transparent"
                      : "bg-white text-gray-700 border-gray-200 hover:border-gray-300"
                  }`}
                  style={
                    activeTeamId === team.id ? { backgroundColor: "#1a2744", borderColor: "#1a2744" } : {}
                  }
                >
                  {team.name}
                </button>
              ))}
            </div>
          </div>

          {/* Player selector */}
          <div>
            <div className="text-xs text-gray-500 uppercase tracking-wider mb-2 font-semibold">
              Гравець:
            </div>
            <select
              className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm bg-white focus:outline-none focus:ring-2"
              style={{ "--tw-ring-color": "#1a2744" } as React.CSSProperties}
              value={selectedPlayerId ?? ""}
              onChange={(e) => setSelectedPlayerId(e.target.value ? parseInt(e.target.value) : null)}
            >
              <option value="">Оберіть гравця...</option>
              {activePlayers.map((p) => (
                <option key={p.id} value={p.id}>
                  #{p.number} {p.firstName} {p.lastName}
                </option>
              ))}
            </select>
          </div>

          {/* Action buttons */}
          <ActionButtons
            gameId={game.id}
            teamId={activeTeamId}
            playerId={selectedPlayerId}
            disabled={pending}
            btnBlue={btnBlue}
            btnOrange={btnOrange}
            btnNavy={btnNavy}
            btnRed={btnRed}
          />

          {/* Undo button */}
          {game.events.length > 0 && (
            <div className="flex justify-end">
              <button
                onClick={() => {
                  if (confirm("Відмінити останню дію?")) {
                    startTransition(() => undoLastEvent(game.id));
                  }
                }}
                disabled={pending}
                className="flex items-center gap-2 bg-gray-100 hover:bg-red-50 border border-gray-200 hover:border-red-300 text-gray-600 hover:text-red-600 text-sm px-4 py-2 rounded-xl font-medium transition-all disabled:opacity-40"
              >
                ↩ Відмінити останню дію
              </button>
            </div>
          )}
        </>
      )}

      {/* Action log */}
      <ActionLog
        events={game.events}
        homeTeam={game.homeTeam}
        awayTeam={game.awayTeam}
        homeScore={game.homeScore}
        awayScore={game.awayScore}
      />
    </div>
  );
}

structure.components/live-tracker/ScoreButtons.tsx:
"use client";

import { useTransition } from "react";
import { addScore, addFoul } from "@/actions/game";

interface Props {
  gameId: number;
  teamId: number;
  playerId: number | null;
  disabled?: boolean;
}

export default function ScoreButtons({ gameId, teamId, playerId, disabled }: Props) {
  const [pending, startTransition] = useTransition();

  const handleScore = (points: 1 | 2 | 3) => {
    if (!playerId) return;
    startTransition(async () => { await addScore(gameId, teamId, playerId, points); });
  };

  const handleFoul = () => {
    if (!playerId) return;
    startTransition(async () => { await addFoul(gameId, teamId, playerId); });
  };

  const isDisabled = disabled || pending || !playerId;

  return (
    <div className="space-y-3">
      <div className="grid grid-cols-2 gap-3">
        <button
          onClick={() => handleScore(1)}
          disabled={isDisabled}
          className="py-4 rounded-xl font-bold text-lg text-white transition-all active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
          style={{ backgroundColor: "#3b82f6" }}
        >
          +1 Штрафний
        </button>
        <button
          onClick={() => handleScore(2)}
          disabled={isDisabled}
          className="py-4 rounded-xl font-bold text-lg text-white transition-all active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
          style={{ backgroundColor: "#f97316" }}
        >
          +2 Двоочковий
        </button>
      </div>
      <button
        onClick={() => handleScore(3)}
        disabled={isDisabled}
        className="w-full py-4 rounded-xl font-bold text-lg text-white transition-all active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
        style={{ backgroundColor: "#1a2744" }}
      >
        +3 Триочковий
      </button>
      <button
        onClick={handleFoul}
        disabled={isDisabled}
        className="w-full py-3 rounded-xl font-semibold text-sm text-white bg-red-500 hover:bg-red-600 transition-all active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
      >
        Фол
      </button>
    </div>
  );
}

structure.components/live-tracker/TeamRoster.tsx:
"use client";

import { useState, useTransition } from "react";
import { addPlayer, removePlayer } from "@/actions/game";
import type { Player } from "@prisma/client";

interface Props {
  team: { id: number; name: string; players: Player[] };
  gameId: number;
}

export default function TeamRoster({ team, gameId }: Props) {
  const [open, setOpen] = useState(false);
  const [num, setNum] = useState("");
  const [first, setFirst] = useState("");
  const [last, setLast] = useState("");
  const [pos, setPos] = useState("");
  const [pending, startTransition] = useTransition();

  const handleAdd = () => {
    const n = parseInt(num);
    if (!first.trim() || !last.trim() || isNaN(n)) return;
    startTransition(async () => {
      await addPlayer(team.id, gameId, first.trim(), last.trim(), n, pos.trim());
      setNum(""); setFirst(""); setLast(""); setPos(""); setOpen(false);
    });
  };

  const handleRemove = (playerId: number) => {
    if (!confirm("Видалити гравця?")) return;
    startTransition(() => removePlayer(playerId, gameId));
  };

  return (
    <div className="bg-white rounded-xl shadow overflow-hidden">
      <div className="px-4 py-3 text-white font-bold text-sm flex items-center justify-between" style={{ backgroundColor: "#1a2744" }}>
        <span>{team.name}</span>
        <button
          onClick={() => setOpen(v => !v)}
          className="text-xs bg-white/20 hover:bg-white/30 px-2 py-0.5 rounded-lg transition-colors"
        >
          {open ? "✕" : "+ Гравець"}
        </button>
      </div>

      {open && (
        <div className="p-3 border-b border-gray-100 bg-gray-50 space-y-2">
          <div className="grid grid-cols-2 gap-2">
            <input
              className="border border-gray-200 rounded-lg px-2 py-1.5 text-xs w-full"
              placeholder="Ім'я"
              value={first}
              onChange={e => setFirst(e.target.value)}
            />
            <input
              className="border border-gray-200 rounded-lg px-2 py-1.5 text-xs w-full"
              placeholder="Прізвище"
              value={last}
              onChange={e => setLast(e.target.value)}
            />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <input
              className="border border-gray-200 rounded-lg px-2 py-1.5 text-xs w-full"
              placeholder="№ (номер)"
              type="number"
              value={num}
              onChange={e => setNum(e.target.value)}
            />
            <input
              className="border border-gray-200 rounded-lg px-2 py-1.5 text-xs w-full"
              placeholder="Позиція (PG…)"
              value={pos}
              onChange={e => setPos(e.target.value)}
            />
          </div>
          <button
            onClick={handleAdd}
            disabled={pending || !first || !last || !num}
            className="w-full py-1.5 rounded-lg text-xs font-bold text-white transition-colors disabled:opacity-40"
            style={{ backgroundColor: "#f97316" }}
          >
            {pending ? "..." : "Додати"}
          </button>
        </div>
      )}

      <div className="divide-y">
        {team.players.map(p => (
          <div key={p.id} className="px-4 py-2 flex items-center gap-3 text-sm group">
            <span className="font-bold text-xs w-6 text-center" style={{ color: "#f97316" }}>
              #{p.number}
            </span>
            <span className="text-gray-800 flex-1">
              {p.firstName} {p.lastName}
            </span>
            {p.position && <span className="text-gray-400 text-xs">{p.position}</span>}
            <button
              onClick={() => handleRemove(p.id)}
              className="opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 text-xs transition-opacity"
              title="Видалити"
            >
              ✕
            </button>
          </div>
        ))}
        {team.players.length === 0 && (
          <div className="px-4 py-4 text-gray-400 text-sm text-center">
            Гравців не додано
          </div>
        )}
      </div>
    </div>
  );
}

structure.components/public/AdBanner.tsx:
import { getSettings } from "@/lib/site-settings";

export default async function AdBanner({ slot }: { slot: "top" | "bottom" }) {
  const keys = [`banner.${slot}.img`, `banner.${slot}.url`, `banner.${slot}.active`];
  const s = await getSettings(keys);

  const img = s[`banner.${slot}.img`] || "";
  const url = s[`banner.${slot}.url`] || "";
  const active = s[`banner.${slot}.active`] !== "false";

  if (!active || !img) {
    return null;
  }

  const imgEl = (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={img}
      alt="Реклама"
      style={{ width: "100%", maxWidth: "728px", borderRadius: "8px", display: "block", margin: "0 auto" }}
    />
  );

  return (
    <div style={{ padding: "10px 16px", backgroundColor: "#f8fafc" }}>
      {url ? (
        <a href={url} target="_blank" rel="noopener noreferrer" style={{ display: "block" }}>
          {imgEl}
        </a>
      ) : imgEl}
    </div>
  );
}

