import { useEffect } from "react";
import { useRouter } from "next/navigation";

interface ChatModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function ChatModal({ isOpen, onClose }: ChatModalProps) {
  const router = useRouter();

  useEffect(() => {
