                  </p>
                </div>
              )}
            </div>
          </form>
        </div>
      </div>
    );
    }
  }

  // ── Render: chat ──────────────────────────────────────────────────────
  const badge = getBadge(user!.hp);
  const userName = `${user!.firstName} ${user!.lastName}`;

  // ── Mobile layout ──────────────────────────────────────────────────────
  if (isMobile && step === "chat" && user) {
