                    <span style={{ fontSize: "22px", flexShrink: 0 }}>{place}</span>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: "13px", fontWeight: 700, color: "white" }}>{rank} — {hp}</div>
                      <div style={{ fontSize: "12px", color: "#94a3b8" }}>{title}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

