                      </div>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: "13px", fontWeight: 700, color: "white" }}>🛡️ {m.name}</div>
                      </div>
                      <span style={{ fontSize: "10px", background: "rgba(124,58,237,0.2)", color: "#a78bfa", padding: "2px 8px", borderRadius: "99px", fontWeight: 700 }}>МОД</span>
                    </div>
