                    <div style={{ fontWeight: 700, fontSize: "13px", lineHeight: 1.3, color: "white", fontFamily: "Exo 2, sans-serif", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>
