                        <div style={{ fontFamily: "Exo 2, sans-serif", fontSize: "13px", fontWeight: isMvp ? 800 : 600, color: isMvp ? "#fbbf24" : isOnline ? "white" : "#6b7280", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
