// ── Компонент кнопки ──────────────────────────────────────────────────────

export default function GamePdfButton({ data }: { data: GamePdfData }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleDownload() {
    setLoading(true);
    setError(null);
    try {
      const [{ default: html2canvas }, { jsPDF }] = await Promise.all([
        import("html2canvas"),
        import("jspdf"),
      ]);

      if (!html2canvas || !jsPDF) {
        throw new Error("Помилка завантаження необхідних модулів");
      }

      // Створюємо прихований контейнер
      const container = document.createElement("div");
      container.style.cssText = [
        "position:fixed",
        "top:-99999px",
        "left:-99999px",
        "width:1140px",
        "background:#fff",
        "z-index:-1",
      ].join(";");
      container.innerHTML = buildProtocolHTML(data);
      document.body.appendChild(container);

      try {
        // Чекаємо рендеринг
        await new Promise((r) => setTimeout(r, 200));

        const canvas = await html2canvas(container, {
          scale: 2,
          useCORS: true,
          logging: false,
          backgroundColor: "#ffffff",
          allowTaint: true,
          imageTimeout: 5000,
        });

        const imgW = canvas.width;
        const imgH = canvas.height;

        // A4 landscape у px при 96dpi
        const pdfW = imgW / 2;
        const pdfH = imgH / 2;

        const pdf = new jsPDF({
          orientation: pdfW > pdfH ? "landscape" : "portrait",
          unit: "px",
          format: [pdfW, pdfH],
          hotfixes: ["px_scaling"],
        });

        pdf.addImage(
          canvas.toDataURL("image/jpeg", 0.95),
          "JPEG",
          0, 0,
          pdfW, pdfH,
        );

        const dateFile = new Date(data.scheduledAt)
          .toLocaleDateString("uk-UA", { day: "2-digit", month: "2-digit", year: "numeric" })
          .replace(/\./g, "-");

        pdf.save(
          `protokol-gry-${data.id}-${data.homeTeam.shortName}-vs-${data.awayTeam.shortName}-${dateFile}.pdf`
        );
      } finally {
        if (document.body.contains(container)) {
          document.body.removeChild(container);
        }
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Невідома помилка";
      setError(`Помилка генерації PDF: ${errorMessage}`);
      console.error("PDF generation error:", err);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div style={{ display: "inline-flex", flexDirection: "column", gap: "8px", alignItems: "flex-start" }}>
      <button
        onClick={handleDownload}
        disabled={loading}
        style={{
          display: "inline-flex",
          alignItems: "center",
          gap: "7px",
          padding: "8px 18px",
          background: loading ? "#fb923c" : error ? "#dc2626" : "#f97316",
          color: "#fff",
          border: "none",
          borderRadius: "8px",
          fontWeight: 700,
          fontSize: "13px",
          cursor: loading || error ? "not-allowed" : "pointer",
          fontFamily: "inherit",
          transition: "background 0.15s",
          whiteSpace: "nowrap",
        }}
      >
        {loading ? (
          <>
            <span style={{
              display: "inline-block",
              width: 13, height: 13,
              border: "2px solid rgba(255,255,255,0.35)",
              borderTopColor: "#fff",
              borderRadius: "50%",
              animation: "pdfSpin 0.7s linear infinite",
            }} />
            Генерація PDF...
          </>
        ) : error ? (
          <>❌ Помилка</>
        ) : (
          <>📄 Завантажити протокол PDF</>
        )}
        <style>{`@keyframes pdfSpin { to { transform: rotate(360deg); } }`}</style>
      </button>
      {error && (
        <div style={{
          fontSize: "12px",
          color: "#dc2626",
          backgroundColor: "#fee2e2",
          padding: "6px 10px",
          borderRadius: "4px",
          maxWidth: "300px",
        }}>
          {error}
        </div>
      )}
    </div>
  );
}

