interface SponsorBannerProps {
  position: "hero" | "page-top" | "sidebar" | "footer";
  pageType?: string;
}

export default function SponsorBanner({ position, pageType = "main" }: SponsorBannerProps) {
  const sponsorsData: any = JSON.parse(require('fs').readFileSync(require('path').join(process.cwd(), 'lib', 'sponsors.data.json'), 'utf-8'));
  const sponsors = sponsorsData.sponsors.filter((s: any) =>
      s.active &&
      s.positions.includes(position) &&
      (s.pages.includes("all") || s.pages.includes(pageType))
  );

  const sizeMap = {
    hero: { width: "100%", maxWidth: "728px", height: "90px" },
    "page-top": { width: "100%", maxWidth: "728px", height: "90px" },
    sidebar: { width: "300px", height: "250px" },
    footer: { width: "100%", maxWidth: "468px", height: "60px" },
  };

  const size = sizeMap[position];

  if (!sponsors.length) {
    return (
      <div
        style={{
          ...size,
          margin: "0 auto",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          border: "2px dashed #f46f10",
          borderRadius: "8px",
          backgroundColor: "rgba(244,111,16,0.04)",
          padding: "8px 16px",
          gap: "8px",
        }}
      >
        <span style={{ fontSize: "14px", color: "#f46f10", fontWeight: 600 }}>
          📢 Місце для реклами · Стати партнером ЛДБЛ →
        </span>
        <a
          href="mailto:info@basket.lviv.ua"
          style={{ fontSize: "13px", color: "#f46f10", textDecoration: "underline", fontWeight: 700 }}
        >
          info@basket.lviv.ua
        </a>
      </div>
    );
  }

  const sponsor = sponsors[0];

  return (
    <a
      href={sponsor.url}
      target="_blank"
      rel="noopener noreferrer"
      style={{
        ...size,
        margin: "0 auto",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        border: "1px solid #e5e7eb",
        borderRadius: "8px",
        backgroundColor: "white",
        padding: "8px 16px",
        gap: "12px",
        textDecoration: "none",
        boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
      }}
    >
      {sponsor.logo ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img src={sponsor.logo} alt={sponsor.name} style={{ height: "40px", objectFit: "contain" }} />
      ) : (
        <div
          style={{
            width: "40px", height: "40px", borderRadius: "50%",
            backgroundColor: "#1e2a4a", display: "flex", alignItems: "center",
            justifyContent: "center", color: "white", fontWeight: 900, fontSize: "16px",
          }}
        >
          {sponsor.name[0]}
        </div>
      )}
      <div>
        <div style={{ fontWeight: 700, color: "#1e2a4a", fontSize: "14px" }}>{sponsor.name}</div>
        {sponsor.slogan && <div style={{ fontSize: "12px", color: "#6b7280" }}>{sponsor.slogan}</div>}
      </div>
    </a>
  );
}

structure.components/public/StandingsTable.tsx:
import { prisma } from "@/lib/prisma";

interface StandingsTableProps {
  limit?: number;
  ageGroup?: string;
  tableBg?: string;
  tableHeaderText?: string;
  tableRowOdd?: string;
  tableRowEven?: string;
}

export default async function StandingsTable({
  limit,
  ageGroup,
  tableBg = "#1a2744",
  tableHeaderText = "#ffffff",
  tableRowOdd = "",
  tableRowEven = "",
}: StandingsTableProps) {
  const ag = ageGroup || "younger";
  const season = await prisma.season.findFirst({ where: { isActive: true, ageGroup: ag } }).catch(() => null);

  if (!season) {
    return (
      <div className="bg-white rounded-xl shadow p-8 text-center text-gray-400">
        Даних ще немає для цієї вікової групи
      </div>
    );
  }

  const standings = await prisma.standing.findMany({
    where: { seasonId: season.id },
    include: { team: true },
    orderBy: [{ wins: "desc" }, { pointsFor: "desc" }],
    take: limit,
  }).catch(() => []);

  return (
    <div className="bg-white rounded-xl shadow overflow-hidden">
      <div
        className="px-4 py-2 text-xs font-bold uppercase tracking-wider"
        style={{ backgroundColor: tableBg, color: tableHeaderText }}
      >
        Таблиця сезону {season.name}
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="bg-gray-50 border-b text-gray-500 uppercase text-xs">
              <th className="px-3 py-2 text-left w-8">#</th>
              <th className="px-3 py-2 text-left">Команда</th>
              <th className="px-3 py-2 text-center">І</th>
              <th className="px-3 py-2 text-center">П</th>
              <th className="px-3 py-2 text-center">Пр</th>
              <th className="px-3 py-2 text-center">+/-</th>
            </tr>
          </thead>
          <tbody>
            {standings.map((s, i) => (
              <tr
                key={s.id}
                className="border-b last:border-0 transition-colors"
                style={{ backgroundColor: i % 2 === 0 ? (tableRowOdd || "#f8fafc") : (tableRowEven || "#ffffff") }}
              >
                <td className="px-3 py-2 text-gray-500 font-medium">{i + 1}</td>
                <td className="px-3 py-2 font-semibold text-gray-800">{s.team.name}</td>
                <td className="px-3 py-2 text-center text-gray-600">{s.gamesPlayed}</td>
                <td className="px-3 py-2 text-center font-bold" style={{ color: tableBg }}>
                  {s.wins}
                </td>
                <td className="px-3 py-2 text-center text-gray-600">{s.losses}</td>
                <td className="px-3 py-2 text-center text-gray-600">
                  {s.pointsFor - s.pointsAgainst > 0 ? "+" : ""}
                  {s.pointsFor - s.pointsAgainst}
                </td>
              </tr>
            ))}
            {standings.length === 0 && (
              <tr>
                <td colSpan={6} className="px-3 py-6 text-center text-gray-400">
                  Дані відсутні
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

