const structure = backupData.structure || {};

// Список КРИТИЧЕСКИХ файлов для Dashboard
const criticalFiles = [
  'app\\admin\\dashboard\\page.tsx',
  'app\\admin\\dashboard\\AgeGroupTabs.tsx',
  'app\\admin\\dashboard\\error.tsx',
  'app\\admin\\page.tsx',
